package com.spoon.ui;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * How a luck figure is worded, which is the number people screenshot.
 */
public class GroupViewTest
{
	@Test
	public void readsAsAPercentage()
	{
		assertEquals("top 40%", GroupView.percent(0.3994));
		assertEquals("top 70%", GroupView.percent(0.6988));
	}

	/**
	 * The best drops are the ones most likely to round to nothing. A one-in-five-hundred stroke of
	 * luck shown as "top 0%" reads as a bug rather than as the best number on the screen.
	 */
	@Test
	public void theAbsurdOnesDoNotRoundToZero()
	{
		assertEquals("top <1%", GroupView.percent(0.002));
		assertEquals("top <1%", GroupView.percent(0.0000001));
	}

	@Test
	public void onePercentIsStillAPercentage()
	{
		assertEquals("top 1%", GroupView.percent(0.01));
	}
}

package com.spoon.ui;

import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * That a tile runs whatever the action is <em>now</em>, not whatever it was when the tile was built.
 */
public class ActionTileTest
{
	/**
	 * The bug this was written for: two buttons that did nothing.
	 * <p>
	 * The panel is built by injection before the plugin has said what its buttons do, so a tile handed
	 * the action directly keeps the empty default for ever. Reading it through a lambda at click time
	 * is what makes a later hand-over take effect.
	 */
	@Test
	public void picksUpAnActionSetAfterItWasBuilt()
	{
		AtomicInteger runs = new AtomicInteger();

		// Stands in for the panel's field, empty at build time and filled later.
		Runnable[] action = { () -> { } };
		ActionTile tile = new ActionTile("Create", () -> action[0].run());

		tile.press();
		assertEquals("the empty default should have run", 0, runs.get());

		action[0] = runs::incrementAndGet;

		tile.press();
		assertEquals("the action set afterwards should have run", 1, runs.get());
	}
}

package com.spoon.data;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Working out which casket a reward came out of, from whatever the game called it.
 */
public class ClueRewardsTest
{
	/**
	 * The same tier arrives worded three ways depending on which part of the game is speaking, and a
	 * tier that is not recognised means the reward is never scored.
	 */
	@Test
	public void recognisesATierHoweverItIsWorded()
	{
		assertEquals("hard", ClueRewards.tierOf("Clue Scroll (Hard)"));
		assertEquals("hard", ClueRewards.tierOf("Reward Casket (hard)"));
		assertEquals("master", ClueRewards.tierOf("Clue Scroll (Master)"));
		assertEquals("beginner", ClueRewards.tierOf("beginner Treasure Trails"));
	}

	@Test
	public void aMonsterIsNotAClue()
	{
		assertNull(ClueRewards.tierOf("Cockatrice"));
		assertNull(ClueRewards.tierOf("Vorkath"));
		assertNull(ClueRewards.tierOf(null));
	}
}

package com.spoon.data;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LuckTest
{
	/**
	 * Taken from a real Dink message in the group's Discord: Iron boots off Cockatrice, 1 in 128, on
	 * kill 65, which Dink reported as "Top 40% (Lucky)".
	 * <p>
	 * Pinned because agreeing with Dink is a feature. The group has been reading its numbers since
	 * December and a leaderboard that quietly disagreed with them would be argued with, rightly.
	 */
	@Test
	public void agreesWithDink()
	{
		assertEquals(0.40, Luck.shareWhoHaveItBy(128, 65), 0.005);
	}

	@Test
	public void gettingItEarlyIsLucky()
	{
		// A 1 in 5000 on the tenth kill: almost nobody has it that soon.
		double share = Luck.shareWhoHaveItBy(5000, 10);
		assertTrue(share < 0.01);
		assertTrue(Luck.isSpooned(share));
	}

	@Test
	public void goingDryIsNot()
	{
		// The warhammer at 6000 kills, when most people would have had it long before.
		double share = Luck.shareWhoHaveItBy(5000, 6000);
		assertTrue(share > 0.5);
		assertFalse(Luck.isSpooned(share));
	}

	/** Long odds over many kills are where a naive pow() loses its accuracy. */
	@Test
	public void staysPreciseAtLongOdds()
	{
		assertEquals(0.0001, Luck.shareWhoHaveItBy(100000, 10), 1e-7);
		assertTrue(Luck.shareWhoHaveItBy(1000000, 1) > 0);
	}

	@Test
	public void refusesWhatItCannotScore()
	{
		assertEquals(-1, Luck.shareWhoHaveItBy(0, 100), 0);
		assertEquals(-1, Luck.shareWhoHaveItBy(128, 0), 0);
		assertFalse(Luck.isSpooned(-1));
	}
}

package com.spoon.net;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Reading a Discord channel that arrives a chunk at a time.
 *
 * A clan's whole history is more than the service can read into one answer, so it hands back a
 * cursor and is asked again until it says the channel is finished. What is tested here is the asking
 * again: that the totals shown at the end describe the channel rather than the last chunk of it, that
 * a read which gives out partway says what it managed, and that a service which has never heard of
 * chunks is still answered properly.
 */
public class SpoonApiTest
{
	/** A chunk with some drops in it, and where the channel goes on to. */
	private static SpoonApi.Import chunk(int found, int matched, String cursor)
	{
		SpoonApi.Import part = new SpoonApi.Import();
		part.setFound(found);
		part.setSkipped(found * 2);
		part.setMatched(matched);
		part.setImported(matched);
		part.setCursor(cursor);
		part.setDone(cursor == null);
		return part;
	}

	/** Hands back the given chunks in order, and records the cursor it was asked with each time. */
	private static class Channel implements Function<String, SpoonApi.Result<SpoonApi.Import>>
	{
		private final List<SpoonApi.Result<SpoonApi.Import>> chunks;
		private final List<String> asked = new ArrayList<>();

		Channel(List<SpoonApi.Result<SpoonApi.Import>> chunks)
		{
			this.chunks = chunks;
		}

		@Override
		public SpoonApi.Result<SpoonApi.Import> apply(String cursor)
		{
			asked.add(cursor);
			return chunks.get(Math.min(asked.size() - 1, chunks.size() - 1));
		}
	}

	@Test
	public void addsUpEveryChunkIntoOneTotal()
	{
		Channel channel = new Channel(List.of(
			SpoonApi.Result.of(chunk(10, 4, "aaa")),
			SpoonApi.Result.of(chunk(20, 6, "bbb")),
			SpoonApi.Result.of(chunk(5, 1, null))));

		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(false, null, channel);

		assertTrue(result.ok());
		assertEquals(35, result.getValue().getFound());
		assertEquals(70, result.getValue().getSkipped());
		assertEquals(11, result.getValue().getMatched());
		assertEquals(11, result.getValue().getImported());
		assertTrue(result.getValue().isDone());
	}

	/** Each chunk is asked for with the cursor the one before it handed back, starting at nothing. */
	@Test
	public void carriesOnFromWhereTheLastChunkStopped()
	{
		Channel channel = new Channel(List.of(
			SpoonApi.Result.of(chunk(10, 4, "aaa")),
			SpoonApi.Result.of(chunk(20, 6, "bbb")),
			SpoonApi.Result.of(chunk(5, 1, null))));

		SpoonApi.readChannel(false, null, channel);

		assertEquals(3, channel.asked.size());
		assertNull(channel.asked.get(0));
		assertEquals("aaa", channel.asked.get(1));
		assertEquals("bbb", channel.asked.get(2));
	}

	/**
	 * A service that answers with no cursor read the channel in one go, and so has an older service
	 * that has never heard of chunks. Both are finished after one ask.
	 */
	@Test
	public void asksOnceOfAServiceThatDoesNotPage()
	{
		SpoonApi.Import whole = new SpoonApi.Import();
		whole.setFound(120);
		whole.setMatched(30);

		Channel channel = new Channel(List.of(SpoonApi.Result.of(whole)));

		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(false, null, channel);

		assertEquals(1, channel.asked.size());
		assertEquals(120, result.getValue().getFound());
	}

	/** Names not in the group are counted across the whole channel, not just the chunk they were in. */
	@Test
	public void mergesTheNamesItDidNotRecognise()
	{
		SpoonApi.Import first = chunk(10, 4, "aaa");
		Map<String, Integer> one = new LinkedHashMap<>();
		one.put("Zezima", 3);
		one.put("Woox", 1);
		first.setUnmatched(one);

		SpoonApi.Import second = chunk(10, 4, null);
		Map<String, Integer> two = new LinkedHashMap<>();
		two.put("Zezima", 2);
		second.setUnmatched(two);

		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(false, null,
			new Channel(List.of(SpoonApi.Result.of(first), SpoonApi.Result.of(second))));

		assertEquals(Integer.valueOf(5), result.getValue().getUnmatched().get("Zezima"));
		assertEquals(Integer.valueOf(1), result.getValue().getUnmatched().get("Woox"));
	}

	/** Nothing read, nothing to soften: the first failure is handed on exactly as it arrived. */
	@Test
	public void passesOnAFailureOnTheFirstChunk()
	{
		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(false, null,
			new Channel(List.of(SpoonApi.Result.failed("Could not reach the server"))));

		assertEquals("Could not reach the server", result.getError());
	}

	/**
	 * A read that gives out partway says what it managed before it did.
	 *
	 * Half a clan's history is not nothing, and somebody told only that it failed will not press the
	 * button again.
	 */
	@Test
	public void saysWhatItBroughtInBeforeItStopped()
	{
		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(false, null,
			new Channel(List.of(
				SpoonApi.Result.of(chunk(1000, 400, "aaa")),
				SpoonApi.Result.failed("Could not reach the server"))));

		assertTrue(result.getError(), result.getError().contains("Brought in 400 drops"));
		assertTrue(result.getError(), result.getError().contains("Could not reach the server"));
		assertTrue(result.getError(), result.getError().contains("brought in twice"));
	}

	/** The same, for a look that never kept anything: it counts messages rather than drops. */
	@Test
	public void saysHowFarItReadBeforeItStopped()
	{
		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(true, null,
			new Channel(List.of(
				SpoonApi.Result.of(chunk(1000, 400, "aaa")),
				SpoonApi.Result.failed("Could not reach the server"))));

		// A thousand collection log messages and two thousand of everything else.
		assertTrue(result.getError(), result.getError().contains("Read 3,000 messages"));
	}

	/** No bot in the server is the step before importing, and it is the whole answer. */
	@Test
	public void stopsAtOnceWhenThereIsNoBot()
	{
		SpoonApi.Import needsBot = new SpoonApi.Import();
		needsBot.setNeedsBot(true);
		needsBot.setInvite("https://discord.com/oauth2/authorize");

		Channel channel = new Channel(List.of(SpoonApi.Result.of(needsBot)));

		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(false, null, channel);

		assertEquals(1, channel.asked.size());
		assertTrue(result.getValue().isNeedsBot());
	}

	/** The running totals go out after every chunk, so a long read can say how it is getting on. */
	@Test
	public void reportsAsItGoes()
	{
		List<Integer> reported = new ArrayList<>();

		SpoonApi.readChannel(false, running -> reported.add(running.getImported()),
			new Channel(List.of(
				SpoonApi.Result.of(chunk(10, 4, "aaa")),
				SpoonApi.Result.of(chunk(10, 6, "bbb")),
				SpoonApi.Result.of(chunk(10, 1, null)))));

		assertEquals(List.of(4, 10, 11), reported);
	}

	/**
	 * A service that never says it has finished is stopped anyway.
	 *
	 * Nothing in a clan's Discord justifies four hundred chunks, so reaching that is a service
	 * misbehaving, and a plugin that asked it forever would hang the panel it was asked from.
	 */
	@Test
	public void givesUpOnAChannelThatNeverEnds()
	{
		Channel channel = new Channel(List.of(SpoonApi.Result.of(chunk(1, 1, "always more"))));

		SpoonApi.Result<SpoonApi.Import> result = SpoonApi.readChannel(false, null, channel);

		assertTrue(result.ok());
		assertEquals(400, channel.asked.size());
	}
}

package com.spoon.track;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * Turning the name the game uses when something dies into the name its kill count is filed under.
 */
public class KillCountsTest
{
	@Test
	public void ordinaryMonstersJustLowercase()
	{
		assertEquals("cockatrice", KillCounts.cleanName("Cockatrice"));
		assertEquals("demonic gorilla", KillCounts.cleanName("Demonic gorilla"));
	}

	@Test
	public void colonsAreDropped()
	{
		assertEquals("kree'arra", KillCounts.cleanName("Kree'arra"));
		assertEquals("tzkal-zuk", KillCounts.cleanName("TzKal-Zuk"));
	}

	/**
	 * The ones where what dies is not what the kill count is called. Get these wrong and the drop is
	 * recorded with no kill count, which quietly means it cannot be scored.
	 */
	@Test
	public void bossesFiledUnderSomethingElse()
	{
		assertEquals("gauntlet", KillCounts.cleanName("Crystalline Hunllef"));
		assertEquals("corrupted gauntlet", KillCounts.cleanName("Corrupted Hunllef"));
		assertEquals("whisperer", KillCounts.cleanName("The Whisperer"));
		assertEquals("leviathan", KillCounts.cleanName("The Leviathan"));
		assertEquals("hueycoatl", KillCounts.cleanName("The Hueycoatl"));
		assertEquals("barrows chests", KillCounts.cleanName("Barrows"));
	}
}

package com.spoon.ui;

import java.awt.Component;
import java.awt.Dimension;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;

/**
 * Making a group: a name, and that is all.
 * <p>
 * Nothing else is asked for because nothing else is needed. A group has no rules to agree and no
 * settings to get wrong, it is a set of people and their collection logs, and everything worth
 * arguing about comes out of the drops themselves.
 */
public class CreateGroupPanel extends JPanel
{
	public CreateGroupPanel(Consumer<String> onCreate, Runnable onBack)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(Theme.BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(4, 0, 8, Cards.SCROLLBAR_ALLOWANCE));

		add(Header.build("Start a group"));
		add(Cards.gap(14));

		add(Cards.sectionLabel("Group name"));
		add(Cards.gap(4));

		JTextField name = Theme.textField(new JTextField());
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		name.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		name.setFont(Theme.figure(14f));
		add(name);

		add(Cards.gap(6));
		add(Cards.muted("What your mates will see."));

		add(Cards.gap(14));
		add(new ActionTile("Create", () ->
		{
			String typed = name.getText().trim();
			if (typed.isEmpty())
			{
				Cards.warn(this, "Give it a name first.");
				return;
			}

			onCreate.accept(typed);
		}));

		add(Cards.gap(10));
		add(Cards.muted("You will get a code to share. Anyone with it can join."));

		add(Cards.gap(12));
		JButton back = Cards.button("← Back");
		back.setAlignmentX(Component.LEFT_ALIGNMENT);
		back.addActionListener(event -> onBack.run());
		add(back);

		// The only field on the screen, so the cursor belongs in it.
		SwingUtilities.invokeLater(name::requestFocusInWindow);
	}
}

package com.spoon.ui;

import com.spoon.data.Group;
import com.spoon.data.Holder;
import com.spoon.data.Standing;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.ActionEvent;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import net.runelite.client.ui.FontManager;

/**
 * One group, open: who has been spooned the most, and who spooned any given item.
 */
public class GroupView extends JPanel
{
	/** Gold, silver and bronze. Everyone below fourth gets a number, which is its own message. */
	private static final Color[] MEDALS = {
		new Color(240, 176, 62),
		new Color(198, 200, 208),
		new Color(176, 122, 74)
	};

	private final JPanel searchResults = new JPanel();

	/** Held so the offer to share earlier drops can come and go without rebuilding the screen. */
	private final JPanel earlierHolder = new JPanel();

	private Runnable onShareEarlier = () ->
	{
	};

	/** Held so the code block can be opened and shut without rebuilding the screen. */
	private final JPanel codeHolder = new JPanel();

	/**
	 * Shut to begin with, every time.
	 * <p>
	 * The code, the member count and a delete button are wanted about once, when the group is made
	 * and the code goes into Discord. After that they are a large noisy block sitting above the thing
	 * everyone actually opened this for.
	 */
	private boolean codeOpen;

	private Group group;
	private boolean creator;
	private Runnable onLeave;
	private Runnable onImport;

	/**
	 * How far through the Discord channel an import has got, under the button that started it.
	 *
	 * Built with the import section, so it is null until a creator opens the card the button is in,
	 * which is also the only way anybody starts one.
	 */
	private JLabel importProgress;

	/**
	 * @param medal     builds a label carrying the spoon for a place; it fills itself once the game's
	 *                  sprite has loaded
	 * @param onSearch  given what was typed; results come back through {@link #showHolders}
	 */
	public GroupView(
		Group group,
		List<Standing> leaderboard,
		String yourName,
		boolean creator,
		java.util.function.IntFunction<JLabel> medal,
		Consumer<String> onSearch,
		Runnable onBack,
		Runnable onRefresh,
		Runnable onLeave,
		int earlierDrops,
		Runnable onShareEarlier,
		Runnable onImport,
		ClaimsPanel claims,
		Runnable onClaim,
		Consumer<String> onOpenMember)
	{
		setLayout(new BorderLayout());
		setBackground(Theme.BACKGROUND);

		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(Theme.BACKGROUND);
		body.setBorder(BorderFactory.createEmptyBorder(4, 0, 8, Cards.SCROLLBAR_ALLOWANCE));

		body.add(backRow(onBack, onRefresh));
		body.add(Cards.gap(6));

		body.add(Header.build(group.getName()));
		body.add(Cards.gap(10));

		this.group = group;
		this.creator = creator;
		this.onLeave = onLeave;
		this.onImport = onImport;

		codeHolder.setLayout(new BoxLayout(codeHolder, BoxLayout.Y_AXIS));
		codeHolder.setBackground(Theme.BACKGROUND);
		codeHolder.setAlignmentX(Component.LEFT_ALIGNMENT);
		renderCode();
		body.add(codeHolder);

		this.onShareEarlier = onShareEarlier;

		earlierHolder.setLayout(new BoxLayout(earlierHolder, BoxLayout.Y_AXIS));
		earlierHolder.setBackground(Theme.BACKGROUND);
		earlierHolder.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(earlierHolder);
		setEarlierDrops(earlierDrops);

		body.add(Cards.gap(14));
		body.add(Cards.sectionLabel("Spooniest in the group"));
		body.add(Cards.gap(4));
		body.add(leaderboardList(leaderboard, yourName, medal, onOpenMember));

		body.add(Cards.gap(16));
		body.add(claimsHeader(onClaim));
		body.add(Cards.gap(4));
		body.add(claims);

		body.add(Cards.gap(16));
		body.add(Cards.sectionLabel("Who spooned it?"));
		body.add(Cards.gap(4));
		body.add(searchRow(onSearch));

		searchResults.setLayout(new BoxLayout(searchResults, BoxLayout.Y_AXIS));
		searchResults.setBackground(Theme.BACKGROUND);
		searchResults.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(Cards.gap(4));
		body.add(searchResults);

		add(body, BorderLayout.NORTH);
	}

	private JPanel backRow(Runnable onBack, Runnable onRefresh)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		JButton back = Cards.button("← Groups");
		back.addActionListener(event -> onBack.run());
		row.add(back);

		row.add(javax.swing.Box.createHorizontalStrut(4));

		JButton refresh = Cards.button("Refresh");
		refresh.addActionListener(event -> onRefresh.run());
		row.add(refresh);

		return row;
	}

	/**
	 * "Up for a vote", with the way to add one beside it.
	 * <p>
	 * Anyone may claim. Nobody may carry their own, so putting the button here rather than hiding it
	 * behind the creator's block is safe and is where people will look for it.
	 */
	private JPanel claimsHeader(Runnable onClaim)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		row.add(Cards.sectionLabel("Up for a vote"), BorderLayout.WEST);

		JButton add = Cards.button("Claim a drop");
		add.setToolTipText("For something you got before this plugin was watching");
		add.addActionListener(event -> onClaim.run());
		row.add(add, BorderLayout.EAST);

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/**
	 * Changes how many earlier drops are on offer, without redrawing the screen.
	 * <p>
	 * Called the moment sharing is agreed to rather than after the send comes back, so the card goes
	 * at once. Waiting for the round trip would leave it sitting there for a few seconds still
	 * offering what has just been given away.
	 */
	public void setEarlierDrops(int count)
	{
		earlierHolder.removeAll();

		if (count > 0)
		{
			earlierHolder.add(Cards.gap(8));
			earlierHolder.add(shareEarlier(count, onShareEarlier));
		}

		earlierHolder.revalidate();
		earlierHolder.repaint();
	}

	/**
	 * The offer to hand over what was already recorded before joining.
	 * <p>
	 * Offered rather than done, because joining a group should not push a collection log built up over
	 * years at everyone without being asked. Shown only while there is something to send, so it
	 * disappears once it has been taken up.
	 */
	private JPanel shareEarlier(int count, Runnable onShare)
	{
		JPanel card = Cards.card();

		JLabel heading = new JLabel(count + (count == 1 ? " earlier drop" : " earlier drops"));
		heading.setFont(Theme.heading());
		heading.setForeground(Theme.GOLD);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(heading);

		card.add(Cards.gap(2));
		card.add(Cards.muted("Recorded before you joined, and not shared with this group."));

		card.add(Cards.gap(6));
		JButton share = Cards.button("Share them");
		share.setAlignmentX(Component.LEFT_ALIGNMENT);
		share.addActionListener(event -> onShare.run());
		card.add(share);

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/** Fills {@link #codeHolder}, open or shut. */
	private void renderCode()
	{
		codeHolder.removeAll();
		codeHolder.add(codeToggle());

		if (codeOpen)
		{
			codeHolder.add(Cards.gap(3));
			codeHolder.add(codeCard());
		}

		codeHolder.revalidate();
		codeHolder.repaint();
	}

	/** The one slim row that is always there, and the whole block when it is shut. */
	private JPanel codeToggle()
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		JLabel label = new JLabel((codeOpen ? "− " : "+ ")
			+ (creator ? "Your group code" : "Group code"));
		label.setFont(Theme.body());
		label.setForeground(Theme.TEXT_MUTED);
		row.add(label, BorderLayout.CENTER);

		JLabel members = new JLabel(group.getMembers()
			+ (group.getMembers() == 1 ? " member" : " members"));
		members.setFont(Theme.body());
		members.setForeground(Theme.TEXT_MUTED);
		row.add(members, BorderLayout.EAST);

		row.addMouseListener(new java.awt.event.MouseAdapter()
		{
			// mousePressed rather than mouseClicked. Swing only fires a click when the press and the
			// release land on the same component with the mouse not having moved between them, so a
			// pixel of drift silently does nothing, which reads as the plugin ignoring you.
			@Override
			public void mousePressed(java.awt.event.MouseEvent event)
			{
				codeOpen = !codeOpen;
				renderCode();
			}
		});

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** The code, shown large, it is what gets pasted into Discord and read back by hand. */
	/**
	 * Shows how an import is getting on. Empty puts the line away again.
	 */
	public void importProgress(String text)
	{
		if (importProgress == null)
		{
			return;
		}

		importProgress.setText(text);
		importProgress.setVisible(!text.isEmpty());
		revalidate();
		repaint();
	}

	private JPanel codeCard()
	{
		JPanel card = Cards.card();

		JLabel code = new JLabel(group.getCode());
		code.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 18f));
		code.setForeground(Theme.GOLD);
		code.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(code);

		card.add(Cards.gap(2));
		card.add(Cards.muted("Share this so people can join. Made by " + group.getCreatorRsn() + "."));

		if (creator)
		{
			// In here with the code and the delete button, because it belongs to the same rare visit:
			// set the group up, share the code, bring in the history, and then never look again.
			card.add(Cards.gap(8));
			card.add(Cards.sectionLabel("Import from Discord"));
			card.add(Cards.gap(2));
			card.add(Cards.muted("If your group posts Dink messages to a channel, the drops in it can "
				+ "be brought in. You are shown what was found before anything is kept."));

			card.add(Cards.gap(4));
			JButton go = Cards.button("Look for history");
			go.setAlignmentX(Component.LEFT_ALIGNMENT);
			go.addActionListener(event -> onImport.run());
			card.add(go);

			// Reading a channel of any size takes a while, and it is read in pieces, so there is
			// something true to say the whole time it is happening.
			importProgress = Cards.muted("");
			importProgress.setAlignmentX(Component.LEFT_ALIGNMENT);
			importProgress.setVisible(false);
			card.add(Cards.gap(2));
			card.add(importProgress);
		}

		card.add(Cards.gap(8));
		JButton leave = Cards.button(creator ? "Delete group" : "Leave group");
		leave.setAlignmentX(Component.LEFT_ALIGNMENT);
		leave.addActionListener((ActionEvent event) -> onLeave.run());
		card.add(leave);

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private JPanel leaderboardList(
		List<Standing> leaderboard, String yourName, java.util.function.IntFunction<JLabel> medal,
		Consumer<String> onOpenMember)
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(Theme.BACKGROUND);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (leaderboard.isEmpty())
		{
			list.add(Cards.muted("Nobody has scored a drop yet."));
			return list;
		}

		for (Standing standing : leaderboard)
		{
			list.add(standingRow(standing, yourName, medal, onOpenMember));
			list.add(Cards.gap(3));
		}

		return list;
	}

	private JPanel standingRow(
		Standing standing, String yourName, java.util.function.IntFunction<JLabel> medal,
		Consumer<String> onOpenMember)
	{
		boolean you = standing.getRsn().equalsIgnoreCase(yourName == null ? "" : yourName);

		JPanel row = new JPanel(new BorderLayout(Cards.ROW_GAP, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(5, Cards.ROW_PAD, 5, Cards.ROW_PAD));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		// The top three get a spoon; everyone else gets their number. Fourth place being plainly not a
		// medal is most of the joke.
		if (standing.getPlace() <= 3)
		{
			row.add(medal.apply(standing.getPlace()), BorderLayout.WEST);
		}
		else
		{
			JLabel place = new JLabel(standing.getPlace() + ordinal(standing.getPlace()));
			place.setFont(FontManager.getRunescapeSmallFont());
			place.setForeground(Theme.TEXT_MUTED);
			place.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 6));
			row.add(place, BorderLayout.WEST);
		}

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		JLabel name = new JLabel(Cards.wrap(standing.getRsn(), Cards.NAME_WRAP));
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(you ? Theme.GOLD : Theme.TEXT);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		text.add(Cards.mutedInRow("account luck " + percent(standing.getAvgShare())
			+ " · " + standing.getScored() + " scored"));
		row.add(text, BorderLayout.CENTER);

		JLabel spoons = new JLabel(String.valueOf(standing.getSpoons()));
		spoons.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 15f));
		spoons.setForeground(standing.getPlace() <= 3 ? MEDALS[standing.getPlace() - 1] : Theme.TEXT);
		row.add(spoons, BorderLayout.EAST);

		// The whole row opens them, not just the name: a name is a small target in a sidebar, and
		// everything on the row is about that person anyway.
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		row.addMouseListener(new java.awt.event.MouseAdapter()
		{
			// mousePressed rather than mouseClicked. Swing only fires a click when the press and the
			// release land on the same component with the mouse not having moved between them, so a
			// pixel of drift silently does nothing, which reads as the plugin ignoring you.
			@Override
			public void mousePressed(java.awt.event.MouseEvent event)
			{
				onOpenMember.accept(standing.getRsn());
			}

			@Override
			public void mouseEntered(java.awt.event.MouseEvent event)
			{
				row.setBackground(Theme.CARD_HOVER);
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent event)
			{
				row.setBackground(Theme.CARD);
			}
		});

		Cards.fitRow(row);
		return row;
	}

	private JPanel searchRow(Consumer<String> onSearch)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JTextField query = Theme.textField(new JTextField());
		query.setFont(Theme.body());
		row.add(query, BorderLayout.CENTER);

		JButton go = Cards.button("Search");
		go.addActionListener(event -> onSearch.accept(query.getText().trim()));
		row.add(go, BorderLayout.EAST);

		// Enter searches, because nobody reaches for a button after typing a name.
		query.addActionListener(event -> onSearch.accept(query.getText().trim()));

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		return row;
	}

	/**
	 * Fills in the results of a search: everyone who has that item, luckiest first.
	 */
	public void showHolders(
		String itemName, List<Holder> holders, java.util.function.IntFunction<JLabel> medal,
		ItemIcons icons)
	{
		searchResults.removeAll();

		if (holders.isEmpty())
		{
			searchResults.add(Cards.muted("Nobody in this group has " + itemName + "."));
			searchResults.revalidate();
			searchResults.repaint();
			return;
		}

		JPanel heading = new JPanel(new BorderLayout(Cards.ROW_GAP, 0));
		heading.setBackground(Theme.BACKGROUND);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		heading.add(icons.label(holders.get(0).getItemId(), itemName), BorderLayout.WEST);
		heading.add(Cards.sectionLabel(itemName), BorderLayout.CENTER);
		heading.setMaximumSize(new Dimension(Integer.MAX_VALUE, heading.getPreferredSize().height));
		searchResults.add(heading);
		searchResults.add(Cards.gap(4));

		for (Holder holder : holders)
		{
			searchResults.add(holderRow(holder, medal, icons));
			searchResults.add(Cards.gap(3));
		}

		searchResults.revalidate();
		searchResults.repaint();
	}

	public void showSearchMessage(String message)
	{
		searchResults.removeAll();
		searchResults.add(Cards.muted(message));
		searchResults.revalidate();
		searchResults.repaint();
	}

	private JPanel holderRow(
		Holder holder, java.util.function.IntFunction<JLabel> medal, ItemIcons icons)
	{
		JPanel row = new JPanel(new BorderLayout(Cards.ROW_GAP, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(Cards.ROW_PAD, Cards.ROW_PAD, Cards.ROW_PAD, Cards.ROW_PAD));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Only the scored get medals here. Somebody who has the item but never had a kill count
		// recorded is not first, and is not last either, they are simply not in the running.
		if (holder.getShare() != null && holder.getPlace() <= 3)
		{
			row.add(medal.apply(holder.getPlace()), BorderLayout.WEST);
		}

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		JLabel name = new JLabel(Cards.wrap(holder.getRsn(), Cards.NAME_WRAP));
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(Theme.TEXT);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		String detail = holder.getKillCount() != null
			? "kc " + holder.getKillCount()
			: "kill count unknown";

		if (holder.getDenominator() != null)
		{
			detail += " · 1 in " + Math.round(holder.getDenominator());
		}

		if (holder.isClaimed())
		{
			// Typed in rather than seen. Said on the row, so a claimed drop is never mistaken for one
			// the plugin watched happen.
			detail += " · claimed";
		}

		text.add(Cards.mutedInRow(detail));
		row.add(text, BorderLayout.CENTER);

		JLabel luck = new JLabel(holder.getShare() == null ? "-" : percent(holder.getShare()));
		luck.setFont(FontManager.getRunescapeBoldFont());
		luck.setForeground(holder.getShare() == null ? Theme.TEXT_MUTED : luckColour(holder.getShare()));
		row.add(luck, BorderLayout.EAST);

		Cards.fitRow(row);
		return row;
	}

	/**
	 * "top 12%", or "top &lt;1%" for the absurd ones.
	 * <p>
	 * Rounding a one-in-five-hundred stroke of luck down to "top 0%" would read as a bug rather than as
	 * the best number on the screen.
	 */
	static String percent(double share)
	{
		double asPercent = share * 100;
		if (asPercent < 1)
		{
			return "top <1%";
		}

		return "top " + Math.round(asPercent) + "%";
	}

	private static Color luckColour(double share)
	{
		if (share < 0.05)
		{
			return MEDALS[0];
		}

		if (share < 0.25)
		{
			return MEDALS[1];
		}

		if (share < 0.5)
		{
			return MEDALS[2];
		}

		return Theme.TEXT_MUTED;
	}

	private static String ordinal(int place)
	{
		if (place % 100 >= 11 && place % 100 <= 13)
		{
			return "th";
		}

		switch (place % 10)
		{
			case 1:
				return "st";
			case 2:
				return "nd";
			case 3:
				return "rd";
			default:
				return "th";
		}
	}
}

package com.spoon.ui;

import com.spoon.data.Holder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * One person's drops.
 * <p>
 * Newest first, because the commonest question about somebody is what they have just had. Sorted by
 * luck when asked, which is the other question people mean: what is the best thing they have ever
 * done.
 */
public class MemberView extends JPanel
{
	private static final SimpleDateFormat WHEN = new SimpleDateFormat("d MMM yyyy");

	private final JPanel list = new JPanel();
	private final ItemIcons icons;

	private final String rsn;
	private final Consumer<String> onSort;

	private String sort;

	/**
	 * The drops that could be scored, and the drops that could not.
	 * <p>
	 * Kept apart because they answer different questions. A scored drop says how lucky somebody was; an
	 * unscored one says only that they have the thing, because nothing knows the kill count it came on
	 * or the odds of it. Mixed together the second sort drowns the first, and a list of dashes is what
	 * people see instead of the run of numbers they came for.
	 */
	private List<Holder> scored = new java.util.ArrayList<>();
	private List<Holder> unscored = new java.util.ArrayList<>();

	/** Whether the unscored are showing. Shut again whenever a fresh list arrives. */
	private boolean unscoredOpen;

	public MemberView(
		String rsn,
		int spoons,
		int scored,
		double avgShare,
		String sort,
		ItemIcons icons,
		Consumer<String> onSort,
		Runnable onBack)
	{
		this.rsn = rsn;
		this.sort = sort;
		this.icons = icons;
		this.onSort = onSort;

		setLayout(new BorderLayout());
		setBackground(Theme.BACKGROUND);

		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(Theme.BACKGROUND);
		body.setBorder(BorderFactory.createEmptyBorder(4, 0, 8, Cards.SCROLLBAR_ALLOWANCE));

		JButton back = Cards.button("← Leaderboard");
		back.setAlignmentX(Component.LEFT_ALIGNMENT);
		back.addActionListener(event -> onBack.run());
		body.add(back);

		body.add(Cards.gap(6));
		body.add(Header.build(rsn));

		body.add(Cards.gap(10));
		body.add(summary(spoons, scored, avgShare));

		body.add(Cards.gap(12));
		body.add(sortRow());

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(Theme.BACKGROUND);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(Cards.gap(4));
		body.add(list);

		add(body, BorderLayout.NORTH);
	}

	private JPanel summary(int spoons, int scored, double avgShare)
	{
		JPanel card = Cards.card();

		JLabel total = new JLabel(spoons + (spoons == 1 ? " spoon" : " spoons"));
		total.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 18f));
		total.setForeground(Theme.GOLD);
		total.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(total);

		card.add(Cards.gap(2));
		card.add(Cards.muted("out of " + scored + " scored drops · account luck "
			+ GroupView.percent(avgShare)));

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/** Newest or luckiest. Two, because there is no third question anybody asks. */
	private JPanel sortRow()
	{
		JPanel row = new JPanel(new java.awt.GridLayout(1, 2, 6, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		row.add(sortButton("Newest", "recent"));
		row.add(sortButton("Biggest spoon", "luck"));

		return row;
	}

	private JButton sortButton(String label, String value)
	{
		boolean chosen = value.equals(sort);

		JButton button = Cards.button(chosen ? label + " ✓" : label);
		button.setForeground(chosen ? Theme.GOLD : Theme.TEXT_MUTED);
		button.addActionListener(event ->
		{
			if (!value.equals(sort))
			{
				onSort.accept(value);
			}
		});

		return button;
	}

	public void show(List<Holder> drops)
	{
		scored = new java.util.ArrayList<>();
		unscored = new java.util.ArrayList<>();

		for (Holder drop : drops)
		{
			(drop.getShare() == null ? unscored : scored).add(drop);
		}

		// A fresh list is a fresh question, so they go back in the drawer.
		unscoredOpen = false;
		rebuild();
	}

	public void showMessage(String message)
	{
		scored = new java.util.ArrayList<>();
		unscored = new java.util.ArrayList<>();

		list.removeAll();
		list.add(Cards.muted(message));
		list.revalidate();
		list.repaint();
	}

	private void rebuild()
	{
		list.removeAll();

		if (scored.isEmpty() && unscored.isEmpty())
		{
			list.add(Cards.muted(rsn + " has nothing recorded in this group yet."));
		}

		for (Holder drop : scored)
		{
			list.add(row(drop));
			list.add(Cards.gap(3));
		}

		if (!unscored.isEmpty())
		{
			list.add(Cards.gap(5));
			list.add(drawer());

			if (unscoredOpen)
			{
				list.add(Cards.gap(4));
				list.add(Cards.muted("Nothing knows the kill count these came on, or the odds of them. "
					+ "They are kept and shown, and never ranked."));
				list.add(Cards.gap(4));

				for (Holder drop : unscored)
				{
					list.add(row(drop));
					list.add(Cards.gap(3));
				}
			}
		}

		list.revalidate();
		list.repaint();
	}

	/**
	 * The drops nothing could score, folded away under the rest.
	 * <p>
	 * Out of the way rather than gone. They are real drops and somebody looking for one wants to find
	 * it, but a column of dashes above the numbers is the thing people were complaining about, and the
	 * count on the button says how many are down there without anybody having to open it.
	 */
	private JButton drawer()
	{
		JButton toggle = Cards.button(
			(unscoredOpen ? "Hide " : "Show ") + unscored.size() + " not scored");

		toggle.setAlignmentX(Component.LEFT_ALIGNMENT);
		toggle.setForeground(Theme.TEXT_MUTED);
		toggle.addActionListener(event ->
		{
			unscoredOpen = !unscoredOpen;
			rebuild();
		});

		return toggle;
	}

	private JPanel row(Holder drop)
	{
		JPanel row = new JPanel(new BorderLayout(Cards.ROW_GAP, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(Cards.ROW_PAD, Cards.ROW_PAD, Cards.ROW_PAD, Cards.ROW_PAD));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		// By id when there is one, by name when there is not: an imported drop carries only a name,
		// because that is all Dink writes.
		row.add(icons.label(drop.getItemId(), drop.getItemName()), BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		// Wrapped: item names run to "Ancient ceremonial mask" and a plain label asks for the lot on
		// one line, which is enough to widen the whole sidebar.
		JLabel name = new JLabel(Cards.wrap(drop.getItemName(), Cards.NAME_WRAP));
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(Theme.TEXT);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		StringBuilder detail = new StringBuilder();
		if (drop.getKillCount() != null)
		{
			detail.append("kc ").append(drop.getKillCount());
		}
		else if (drop.getSource() != null && !drop.getSource().isEmpty())
		{
			detail.append(drop.getSource());
		}

		if (drop.getDenominator() != null)
		{
			detail.append(detail.length() > 0 ? " · " : "")
				.append("1 in ").append(Math.round(drop.getDenominator()));
		}

		if (drop.isClaimed())
		{
			// Voted in rather than watched happening, and said so wherever it appears.
			detail.append(detail.length() > 0 ? " · " : "").append("claimed");
		}

		text.add(Cards.mutedInRow(detail.length() == 0 ? "no details" : detail.toString()));
		text.add(Cards.mutedInRow(WHEN.format(new Date(drop.getObtainedAt()))));

		row.add(text, BorderLayout.CENTER);

		JLabel luck = new JLabel(drop.getShare() == null ? "-" : GroupView.percent(drop.getShare()));
		luck.setFont(FontManager.getRunescapeBoldFont());
		luck.setForeground(drop.getShare() == null ? Theme.TEXT_MUTED : colourFor(drop.getShare()));
		row.add(luck, BorderLayout.EAST);

		Cards.fitRow(row);
		return row;
	}

	private static Color colourFor(double share)
	{
		if (share < 0.05)
		{
			return new Color(240, 176, 62);
		}

		if (share < 0.25)
		{
			return new Color(198, 200, 208);
		}

		if (share < 0.5)
		{
			return new Color(176, 122, 74);
		}

		return Theme.TEXT_MUTED;
	}
}

package com.spoon.ui;

import java.awt.Component;
import java.awt.Dimension;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;

/**
 * Joining: a code, and a button.
 */
public class JoinGroupPanel extends JPanel
{
	public JoinGroupPanel(Consumer<String> onJoin, Runnable onBack)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(Theme.BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(4, 0, 8, Cards.SCROLLBAR_ALLOWANCE));

		add(Header.build("Join a group"));
		add(Cards.gap(14));

		add(Cards.sectionLabel("Group code"));
		add(Cards.gap(4));

		JTextField code = Theme.textField(new JTextField());
		code.setAlignmentX(Component.LEFT_ALIGNMENT);
		code.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));
		// Big and centred, because a code is read off a phone or out of Discord and typed by hand.
		code.setFont(Theme.figure(18f));
		code.setHorizontalAlignment(JTextField.CENTER);
		add(code);

		add(Cards.gap(6));
		add(Cards.muted("Six characters, from whoever made the group."));

		add(Cards.gap(14));
		add(new ActionTile("Join", () ->
		{
			String typed = code.getText().trim().toUpperCase();
			if (typed.isEmpty())
			{
				Cards.warn(this, "Paste the code first.");
				return;
			}

			onJoin.accept(typed);
		}));

		add(Cards.gap(10));
		add(Cards.muted("Your drops from here on will be compared with theirs. Nothing you already "
			+ "have is sent unless you ask for it."));

		add(Cards.gap(12));
		JButton back = Cards.button("← Back");
		back.setAlignmentX(Component.LEFT_ALIGNMENT);
		back.addActionListener(event -> onBack.run());
		add(back);

		SwingUtilities.invokeLater(code::requestFocusInWindow);
	}
}

package com.spoon.ui;

import java.awt.BasicStroke;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;

/**
 * One group you are in, on the front screen.
 * <p>
 * Painted for the same reason as {@link ActionTile}, and given its own outline because somebody in
 * three groups needs to see three separate things rather than one list of text.
 */
public class GroupCard extends JPanel
{
	private static final int HEIGHT = 44;

	private final String name;
	private final String detail;
	private final Runnable onClick;

	private boolean hovered;

	public GroupCard(String name, String detail, Runnable onClick)
	{
		this.name = name;
		this.detail = detail;
		this.onClick = onClick;

		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setPreferredSize(new Dimension(10, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				hovered = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovered = false;
				repaint();
			}

			// mousePressed rather than mouseClicked. Swing only fires a click when the press and the
			// release land on the same component with the mouse not having moved between them, so a
			// pixel of drift silently does nothing, which reads as the plugin ignoring you.
			@Override
			public void mousePressed(MouseEvent event)
			{
				onClick.run();
			}
		});
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D graphics = Theme.smooth((Graphics2D) g.create());

		int width = getWidth();
		int height = getHeight();

		graphics.setColor(hovered ? Theme.CARD_HOVER : Theme.CARD);
		graphics.fillRoundRect(0, 0, width - 1, height - 1, 6, 6);

		graphics.setColor(hovered ? Theme.GOLD : Theme.GOLD_DIM);
		graphics.setStroke(new BasicStroke(1f));
		graphics.drawRoundRect(0, 0, width - 1, height - 1, 6, 6);

		// A gold spine down the left, so a stack of these reads as a list of things rather than a set
		// of boxes.
		graphics.fillRect(0, 1, 3, height - 2);

		graphics.setFont(Theme.heading());
		graphics.setColor(Theme.GOLD);
		FontMetrics metrics = graphics.getFontMetrics();
		graphics.drawString(name, 12, 6 + metrics.getAscent());

		graphics.setFont(Theme.body());
		graphics.setColor(Theme.TEXT_MUTED);
		graphics.drawString(detail, 12, height - 10);

		// The chevron: this opens something.
		graphics.setColor(hovered ? Theme.GOLD : Theme.GOLD_DIM);
		graphics.setStroke(new BasicStroke(2f));
		int mid = height / 2;
		graphics.drawLine(width - 16, mid - 5, width - 11, mid);
		graphics.drawLine(width - 11, mid, width - 16, mid + 5);

		graphics.dispose();
	}
}

package com.spoon.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.BorderFactory;
import javax.swing.JTextField;
import javax.swing.border.Border;
import net.runelite.client.ui.FontManager;

/**
 * The look of the thing.
 * <p>
 * RuneLite's own palette is flat grey on flat grey, which is right for a tool you glance at and wrong
 * for something people open to see whether they are winning. This is a darker, slightly blue base with
 * gold on top of it, gold because that is what a scoreboard is, and because it reads as a prize
 * rather than as an interface.
 * <p>
 * Kept in one place so a colour can be changed once rather than in nine panels.
 */
public final class Theme
{
	/** Near-black with a little blue in it. Flat grey is what made the first attempt look dreary. */
	public static final Color BACKGROUND = new Color(24, 25, 31);

	/** Cards sit just above the background rather than being outlined, which is quieter and reads better. */
	public static final Color CARD = new Color(35, 37, 46);
	public static final Color CARD_HOVER = new Color(45, 48, 60);

	/** The prize colour. Used for anything that is a score, a code, or a call to action. */
	public static final Color GOLD = new Color(240, 176, 62);
	public static final Color GOLD_DIM = new Color(150, 110, 40);

	/** For a challenge that is live right now. */
	public static final Color LIVE = new Color(93, 200, 120);

	public static final Color TEXT = new Color(228, 228, 232);
	public static final Color TEXT_MUTED = new Color(150, 152, 163);

	private Theme()
	{
	}

	/**
	 * The plugin's own name, larger than anything else on the panel.
	 */
	public static Font title()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 22f);
	}

	/** The label on a tile button. Big enough to read without looking for it. */
	public static Font tile()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 15f);
	}

	public static Font heading()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 14f);
	}

	public static Font body()
	{
		return FontManager.getRunescapeSmallFont();
	}

	/**
	 * A number worth looking at, a score, a countdown, a challenge code.
	 */
	public static Font figure(float size)
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, size);
	}

	/**
	 * Swing draws a text field white unless told otherwise, which is where the bright box in the
	 * middle of a dark panel came from.
	 */
	public static JTextField textField(JTextField field)
	{
		field.setBackground(CARD);
		field.setForeground(TEXT);
		field.setCaretColor(GOLD);
		field.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(58, 61, 74)),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)));
		field.setFont(body());
		return field;
	}

	public static Border cardBorder()
	{
		return BorderFactory.createEmptyBorder(8, 10, 8, 10);
	}

	/**
	 * Turns antialiasing on before anything is drawn by hand. Without it the rounded corners look
	 * chewed.
	 */
	public static Graphics2D smooth(Graphics2D graphics)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		return graphics;
	}
}

package com.spoon.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;

/**
 * One of the two things you can do from the front screen, drawn rather than themed.
 * <p>
 * A Swing button cannot be made to look like this without fighting its look and feel the whole way,
 * and the result still changes shape on someone else's machine. Painting it means the gold outline,
 * the fill and the lift on hover are the same everywhere.
 */
public class ActionTile extends JPanel
{
	private static final int HEIGHT = 46;

	private final String label;
	private final Runnable onClick;

	private boolean hovered;

	public ActionTile(String label, Runnable onClick)
	{
		this.label = label;
		this.onClick = onClick;

		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setPreferredSize(new Dimension(10, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));

		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				hovered = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent event)
			{
				hovered = false;
				repaint();
			}

			// mousePressed rather than mouseClicked. Swing only fires a click when the press and the
			// release land on the same component with the mouse not having moved between them, so a
			// pixel of drift silently does nothing, which reads as the plugin ignoring you.
			@Override
			public void mousePressed(MouseEvent event)
			{
				onClick.run();
			}
		});
	}

	/** Runs the tile's action, as a click does. Here so a test can press it without a mouse. */
	void press()
	{
		onClick.run();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D graphics = Theme.smooth((Graphics2D) g.create());

		int width = getWidth();
		int height = getHeight();

		graphics.setColor(hovered ? Theme.CARD_HOVER : Theme.CARD);
		graphics.fillRoundRect(0, 0, width - 1, height - 1, 8, 8);

		// The outline is what makes it read as a button rather than a heading. Brighter on hover, so
		// the thing under the cursor is obvious without anything moving.
		graphics.setColor(hovered ? Theme.GOLD : Theme.GOLD_DIM);
		graphics.setStroke(new BasicStroke(hovered ? 2f : 1f));
		graphics.drawRoundRect(1, 1, width - 3, height - 3, 8, 8);

		graphics.setFont(Theme.tile());
		graphics.setColor(hovered ? Theme.GOLD : new Color(226, 190, 130));

		FontMetrics metrics = graphics.getFontMetrics();
		int x = (width - metrics.stringWidth(label)) / 2;
		int y = (height - metrics.getHeight()) / 2 + metrics.getAscent();
		graphics.drawString(label, x, y);

		graphics.dispose();
	}
}

package com.spoon.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ButtonGroup;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import javax.swing.SwingConstants;
import net.runelite.client.ui.FontManager;

/**
 * Shared building blocks, so the panels look like one plugin rather than several.
 * <p>
 * Carried over from GearForge along with the lessons in it: a centred child in a vertical BoxLayout
 * indents everything below it, and text inside a row has to be narrower than the panel or it pushes
 * whatever sits beside it off the edge.
 */
final class Cards
{
	/** Left accent strip width on a card, in pixels. */
	private static final int ACCENT = 3;

	/** Red rather than the brand orange, so a warning does not read as ordinary highlighting. */
	private static final Color WARNING_COLOR = new Color(220, 90, 70);

	/**
	 * Secondary text. RuneLite's MEDIUM_GRAY_COLOR on the panel background is grey-on-grey and was
	 * reported as hard to read; this keeps the hierarchy while staying legible.
	 */
	private static final Color MUTED_TEXT = Theme.TEXT_MUTED;

	/**
	 * Rows sit inside a scroll pane, and a trailing value would otherwise be clipped by the scrollbar.
	 */
	static final int SCROLLBAR_ALLOWANCE = 12;

	/**
	 * How wide a row may actually be.
	 *
	 * 225 for the sidebar, less the panel's own padding of ten each side, less the room a screen
	 * leaves for the scrollbar:
	 *
	 * <pre>225 - 20 - 12 = 193</pre>
	 *
	 * Written down because guessing at it has twice produced a plugin that shoves RuneLite's icons off
	 * the screen and then clips its own text. Anything laid out across a row has to add up to less
	 * than this, including its own borders and gaps.
	 */
	static final int ROW_WIDTH = net.runelite.client.ui.PluginPanel.PANEL_WIDTH - 20 - SCROLLBAR_ALLOWANCE;

	/** An item picture. The sprite is 36 wide; this crops the empty margin rather than the item. */
	static final int ICON = 30;

	/** The gap either side of the middle column of a row. */
	static final int ROW_GAP = 4;

	/** Padding inside a row. */
	static final int ROW_PAD = 4;

	/**
	 * What is left for a name once a row has paid for everything else.
	 *
	 * <pre>193 - 8 padding - 30 icon - 8 gaps - 46 for the luck figure = 101</pre>
	 *
	 * Set below that on purpose. The sum is right but the parts are estimates, a proportional font
	 * makes "top 100%" wider than "top 19%", and a row that only just fits is one long item name away
	 * from not fitting.
	 */
	static final int NAME_WRAP = 86;

	/**
	 * And what is left for the line under it.
	 *
	 * Was a hundred, which overran the row on its own: a hundred for this, eighty-six for the name
	 * above it and the widest of the two is what the middle column asks for, leaving too little for the
	 * luck figure at the end. That figure is the thing people are reading the row for, so it is the
	 * last thing that should be pushed off the side of the panel.
	 */
	static final int DETAIL_WRAP = NAME_WRAP;

	/**
	 * Holds a row to the width there actually is.
	 *
	 * {@link #ROW_WIDTH} was worked out, written down, and never applied to anything, so it described
	 * a row rather than constraining one. A row whose contents wanted more than the sidebar has took
	 * it: the panel cannot scroll sideways, so the right-hand end simply went under the scrollbar and
	 * off the edge, taking the luck figure with it.
	 *
	 * The minimum is left at nothing so a narrower sidebar shrinks the row rather than overflowing it
	 * again, which is the same failure wearing a different width.
	 */
	static void fitRow(JPanel row)
	{
		int height = row.getPreferredSize().height;

		row.setPreferredSize(new Dimension(ROW_WIDTH, height));
		row.setMaximumSize(new Dimension(ROW_WIDTH, height));
		row.setMinimumSize(new Dimension(0, height));
	}

	private Cards()
	{
	}

	/**
	 * A padded block with a subtle darker background, the unit the panel is composed from.
	 */
	static JPanel card()
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(Theme.CARD);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		return card;
	}

	/**
	 * A card with a coloured strip down the left, used for the headline result.
	 */
	static JPanel accentCard(Color accent)
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(Theme.CARD);
		wrapper.setBorder(BorderFactory.createMatteBorder(0, ACCENT, 0, 0, accent));
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		return wrapper;
	}

	/**
	 * Section label, small, uppercase, muted. Used to break the panel into scannable groups.
	 */
	static JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text.toUpperCase());
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return label;
	}

	/**
	 * The one number that matters, rendered large.
	 */
	static JLabel headline(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
		label.setForeground(Theme.GOLD);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A setup or section title, larger than body text so a list of setups scans by name.
	 */
	static JLabel title(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 13f));
		label.setForeground(Theme.TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A prominent warning block, a coloured strip and bold text, for things the player needs to act
	 * on rather than merely notice.
	 */
	static JPanel warning(String text)
	{
		JPanel inner = new JPanel();
		inner.setLayout(new BoxLayout(inner, BoxLayout.Y_AXIS));
		inner.setBackground(Theme.CARD);
		inner.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JLabel label = new JLabel("<html><body style='width:140px'>" + escape(text) + "</body></html>");
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(WARNING_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		inner.add(label);

		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(Theme.CARD);
		card.setBorder(BorderFactory.createMatteBorder(0, ACCENT, 0, 0, WARNING_COLOR));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(inner, BorderLayout.CENTER);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/**
	 * The secondary text colour, for callers that need it on a component this class does not build.
	 */
	static Color mutedColor()
	{
		return MUTED_TEXT;
	}

	/**
	 * Says something went wrong, where the player is already looking. A dialog would take focus off the
	 * game for something as ordinary as a mistyped date.
	 */
	static void warn(java.awt.Component parent, String message)
	{
		javax.swing.JOptionPane.showMessageDialog(
			parent, message, "Boss of the Week", javax.swing.JOptionPane.INFORMATION_MESSAGE);
	}

	static JLabel body(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Theme.TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * Muted, wrapped text for reasons and caveats.
	 */
	/**
	 * Muted text sized to sit inside a row that already has an icon on one side and a value on the
	 * other. The full-width version forces the row wider than the panel, which pushes the value off the
	 * edge entirely.
	 */
	/**
	 * Text that wraps instead of demanding a line to itself.
	 * <p>
	 * A JLabel asks for however much room its text needs on one line, and in a sidebar of fixed width
	 * that is how one long item name widens the whole plugin.
	 */
	static String wrap(String text, int width)
	{
		return "<html><body style='width:" + width + "px'>" + escape(text) + "</body></html>";
	}

	static JLabel mutedInRow(String text)
	{
		JLabel label = new JLabel(wrap(text, DETAIL_WRAP));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	static JLabel muted(String text)
	{
		JLabel label = new JLabel("<html><body style='width:145px'>" + escape(text) + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A labelled form field stacked vertically, which reads better than side-by-side at this width.
	 */
	static JPanel field(String label, JComponent input)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(Theme.BACKGROUND);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel caption = sectionLabel(label);
		panel.add(caption);

		input.setAlignmentX(Component.LEFT_ALIGNMENT);
		input.setMaximumSize(new Dimension(Integer.MAX_VALUE, input.getPreferredSize().height));
		panel.add(input);

		return panel;
	}

	/**
	 * A vertical spacer that is left-aligned like everything else.
	 * <p>
	 * {@link Box#createVerticalStrut} defaults to centre alignment, and a Y_AXIS BoxLayout containing
	 * a mix of alignments indents its children instead of filling the panel, which is what made the
	 * whole sidebar look squashed toward one side.
	 */
	static Component gap(int height)
	{
		Component strut = Box.createVerticalStrut(height);
		((JComponent) strut).setAlignmentX(Component.LEFT_ALIGNMENT);
		return strut;
	}

	/**
	 * A compact button that matches the sidebar rather than the platform look-and-feel.
	 */
	static JButton button(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Theme.TEXT);
		button.setBackground(Theme.CARD);
		button.setFocusPainted(false);
		button.setBorderPainted(false);
		button.setOpaque(true);
		// Tight horizontal padding: at 225px, three buttons in a row have barely 60px each, and
		// generous padding is what truncated "Off task" into "Off...".
		button.setBorder(BorderFactory.createEmptyBorder(4, 3, 4, 3));
		button.setFocusPainted(false);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		return button;
	}

	/**
	 * A titled section that expands when clicked, like the panels in the wiki's DPS calculator.
	 * <p>
	 * Used instead of a dropdown where the options benefit from being seen at once, prayers as a grid
	 * of icons, potions as a scrollable list, rather than hidden one-at-a-time behind a combo box.
	 *
	 * @param content shown when expanded; starts hidden
	 * @param decorate given the header button, so callers can hang an icon on it, the sprite and item
	 *                 image loaders are asynchronous, so the icon cannot simply be passed in
	 */
	static JPanel expandable(String title, JComponent content, Consumer<JButton> decorate)
	{
		JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setBackground(Theme.BACKGROUND);
		section.setAlignmentX(Component.LEFT_ALIGNMENT);

		JButton header = button(title + "   +");
		header.setHorizontalAlignment(SwingConstants.LEFT);
		header.setIconTextGap(8);
		// Tall enough that a skill icon sits in the row rather than being clipped by it.
		header.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		header.setPreferredSize(new Dimension(0, 30));
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		decorate.accept(header);

		content.setVisible(false);
		content.setAlignmentX(Component.LEFT_ALIGNMENT);

		header.addActionListener(event ->
		{
			boolean opening = !content.isVisible();
			content.setVisible(opening);
			header.setText(title + (opening ? "   −" : "   +"));
			section.revalidate();
			section.repaint();
		});

		section.add(header);
		section.add(content);
		return section;
	}

	/**
	 * A dropdown styled to match the sidebar. The default Swing combo renders light-on-light here and
	 * stands out badly against RuneLite's dark panels.
	 */
	static <T> JComboBox<T> comboBox(T[] items)
	{
		JComboBox<T> combo = new JComboBox<>(items);
		combo.setFont(FontManager.getRunescapeSmallFont());
		combo.setBackground(Theme.CARD);
		combo.setForeground(Theme.TEXT);
		combo.setFocusable(false);
		combo.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
		combo.setRenderer(new DarkListRenderer());
		combo.setAlignmentX(Component.LEFT_ALIGNMENT);
		// Without a maximum, BoxLayout leaves the combo at its preferred width instead of filling.
		combo.setMaximumSize(new Dimension(Integer.MAX_VALUE, combo.getPreferredSize().height));
		return combo;
	}

	/**
	 * Two or more mutually exclusive options as side-by-side buttons, clearer than a dropdown when
	 * there are only a couple of choices, and it shows the alternative without a click.
	 */
	static JPanel segmented(String[] labels, int selectedIndex, IntConsumer onSelect)
	{
		JPanel row = new JPanel(new GridLayout(1, labels.length, 4, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

		ButtonGroup group = new ButtonGroup();

		for (int i = 0; i < labels.length; i++)
		{
			final int index = i;
			JToggleButton option = new JToggleButton(labels[i]);
			option.setFont(FontManager.getRunescapeSmallFont());
			option.setFocusPainted(false);
			option.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));
			option.setSelected(i == selectedIndex);
			paintToggle(option);

			option.addItemListener(event ->
			{
				paintToggle(option);
				if (option.isSelected())
				{
					onSelect.accept(index);
				}
			});

			group.add(option);
			row.add(option);
		}

		return row;
	}

	private static void paintToggle(JToggleButton option)
	{
		option.setBackground(option.isSelected()
			? Theme.GOLD
			: Theme.CARD);
		option.setForeground(option.isSelected()
			? Theme.CARD
			: Theme.TEXT);
	}

	/**
	 * Keeps the dropdown popup dark instead of the default white list.
	 */
	private static final class DarkListRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(
			JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
		{
			super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);

			setFont(FontManager.getRunescapeSmallFont());
			setBackground(isSelected ? Theme.GOLD : Theme.CARD);
			setForeground(isSelected ? Theme.CARD : Theme.TEXT);
			setBorder(BorderFactory.createEmptyBorder(3, 5, 3, 5));
			return this;
		}
	}

	/**
	 * Item names come from the game and can contain characters that would break the HTML wrapper.
	 */
	static String escape(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.spoon.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;

/**
 * The title, with the spoon beside it.
 * <p>
 * One class so every screen carries the same thing. A heading that shifted by a few pixels between
 * the front page and a group would be noticed without anybody being able to say why.
 */
public final class Header
{
	private static final int LOGO = 34;

	/**
	 * What the words may take up.
	 * <p>
	 * A sidebar is a fixed 225 wide and a JLabel asks for however much room its text needs on one
	 * line, so an unwrapped strapline quietly widens the whole plugin until it shoves RuneLite's own
	 * icons off the screen. That is exactly what happened: the group screen fitted because its
	 * strapline was one short word, and the front screen did not because its was a sentence.
	 */
	/**
	 * What is actually available: the sidebar's width less the padding this sits inside.
	 *
	 * The panel pads by ten each side and the screens leave room for a scrollbar, so asking for the
	 * full 225 asks for more than there is and widens everything by the difference. That is the second
	 * time this has pushed RuneLite's icons off the edge, so the sum is written down rather than
	 * guessed at.
	 */
	private static final int AVAILABLE = net.runelite.client.ui.PluginPanel.PANEL_WIDTH - 32;

	private static final int WORDS_WIDTH = AVAILABLE - LOGO - 8;

	private Header()
	{
	}

	public static JPanel build(String strapline)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel words = new JPanel();
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.setBackground(Theme.BACKGROUND);

		JLabel title = new JLabel("WHO SPOONED IT?");
		title.setFont(Theme.title());
		title.setForeground(Theme.GOLD);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		words.add(title);

		if (strapline != null && !strapline.isEmpty())
		{
			// Wrapped rather than trusted to be short, so no caller can widen the panel by accident.
			JLabel under = new JLabel(
				"<html><body style='width:" + WORDS_WIDTH + "px'>" + strapline + "</body></html>");
			under.setFont(Theme.body());
			under.setForeground(Theme.TEXT_MUTED);
			under.setAlignmentX(Component.LEFT_ALIGNMENT);
			words.add(under);
		}

		row.add(words, BorderLayout.CENTER);

		JLabel logo = new JLabel(new ImageIcon(SpoonIcon.logo(LOGO)));
		logo.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
		row.add(logo, BorderLayout.EAST);

		int height = row.getPreferredSize().height;
		row.setPreferredSize(new Dimension(AVAILABLE, height));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return row;
	}
}

package com.spoon.ui;

import com.spoon.data.DropRates;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/**
 * The picture of an item, found from its name.
 * <p>
 * Needed because a drop brought in from Discord has only a name, Dink writes what dropped, not which
 * item id it was, so without this every imported drop is a row with a blank space where everyone
 * else has a picture.
 * <p>
 * The obvious way round it, {@code ItemManager.search}, answers from the price API and so knows only
 * tradeable items. It finds nothing for a pet, which is the row people most want to look at. So the
 * index is built the other way about: every item any monster drops, asked for its real name once.
 */
@Slf4j
@Singleton
public class ItemIcons
{
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final DropRates dropRates;

	/** Lower-cased name to item id. Empty until the first time an icon is wanted. */
	private final Map<String, Integer> byName = new HashMap<>();

	private volatile boolean built;
	private volatile boolean building;

	@Inject
	private ItemIcons(ItemManager itemManager, ClientThread clientThread, DropRates dropRates)
	{
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.dropRates = dropRates;
	}

	/**
	 * Puts an item's picture on a label, now or once the index has been built.
	 *
	 * @param itemId the id if it is known, or anything below 1 to go looking by name
	 */
	public void applyTo(JLabel label, int itemId, String itemName)
	{
		if (itemId > 0)
		{
			itemManager.getImage(itemId).addTo(label);
			return;
		}

		if (itemName == null || itemName.isEmpty())
		{
			return;
		}

		Integer known = byName.get(itemName.toLowerCase(Locale.ROOT));
		if (known != null)
		{
			itemManager.getImage(known).addTo(label);
			return;
		}

		if (built)
		{
			// Looked for and genuinely not there: a clue reward, or something no monster drops. The row
			// simply goes without a picture rather than showing a wrong one.
			return;
		}

		build(() -> SwingUtilities.invokeLater(() ->
		{
			Integer found = byName.get(itemName.toLowerCase(Locale.ROOT));
			if (found != null)
			{
				itemManager.getImage(found).addTo(label);
				label.revalidate();
				label.repaint();
			}
		}));
	}

	/**
	 * Builds the index once, on the client thread, which is the only one allowed to read an item's
	 * composition.
	 * <p>
	 * Every id in the drop data, which is a few thousand once the duplicates across monsters are
	 * dropped, not the thirty-odd thousand items in the game. Done in one pass because a pass costs
	 * about as much as deciding whether to do a pass.
	 */
	private synchronized void build(Runnable then)
	{
		if (built)
		{
			then.run();
			return;
		}

		if (building)
		{
			// Somebody else is already doing it; their pass fills the same map this label will read.
			return;
		}

		building = true;

		clientThread.invokeLater(() ->
		{
			try
			{
				Set<Integer> ids = new HashSet<>();
				for (String source : dropRates.sources())
				{
					for (DropRates.Drop drop : dropRates.dropsFrom(source))
					{
						ids.add(drop.itemId);
					}
				}

				for (int id : ids)
				{
					ItemComposition composition = itemManager.getItemComposition(id);
					if (composition == null || composition.getName() == null)
					{
						continue;
					}

					// The first id for a name wins. Several ids share one name, noted, charged,
					// placeholder versions, and any of them draws the same picture.
					byName.putIfAbsent(composition.getName().toLowerCase(Locale.ROOT), id);
				}

				log.debug("Indexed {} item names", byName.size());
			}
			catch (RuntimeException e)
			{
				// A missing picture is a cosmetic loss. It must never stop a leaderboard being drawn.
				log.debug("Could not index item names", e);
			}
			finally
			{
				built = true;
				building = false;
				then.run();
			}
		});
	}

	/** A label that fills itself with the item's picture. */
	public JLabel label(int itemId, String itemName)
	{
		JLabel label = new JLabel();

		// Sized up front so a row does not jump when the picture arrives.
		label.setPreferredSize(new java.awt.Dimension(Cards.ICON, 32));
		applyTo(label, itemId, itemName);

		return label;
	}
}

package com.spoon.ui;

import com.spoon.data.Luck;
import com.spoon.data.Spoon;
import com.spoon.track.GroupStore;
import com.spoon.track.SpoonStore;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar.
 * <p>
 * Shows this account's own drops before anything else, because the plugin has to be worth having on
 * its own. A group is something you join later to compare; it is not the price of admission.
 */
@Singleton
public class SpoonPanel extends PluginPanel
{
	private static final SimpleDateFormat WHEN = new SimpleDateFormat("d MMM yyyy");

	private final SpoonStore spoons;
	private final GroupStore groupStore;
	private final ItemIcons icons;

	/** Set by the plugin, so this class need not know how a group is made or opened. */
	private Runnable onCreate = () ->
	{
	};

	private Runnable onJoin = () ->
	{
	};

	private java.util.function.Consumer<String> onOpenGroup = code ->
	{
	};

	private final JPanel content = new JPanel();

	/** Whether the list of your own spoons is open. Shut each time the plugin starts. */
	private boolean spooniestOpen;

	@Inject
	private SpoonPanel(SpoonStore spoons, GroupStore groupStore, ItemIcons icons)
	{
		super(false);

		this.spoons = spoons;
		this.groupStore = groupStore;
		this.icons = icons;

		setLayout(new BorderLayout());
		setBackground(Theme.BACKGROUND);
		setOpaque(true);
		setBorder(BorderFactory.createEmptyBorder());

		content.setLayout(new BorderLayout());
		content.setBackground(Theme.BACKGROUND);
		content.setOpaque(true);
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JScrollPane scroll = new JScrollPane(
			content, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setBackground(Theme.BACKGROUND);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setBackground(Theme.BACKGROUND);
		scroll.getViewport().setBackground(Theme.BACKGROUND);
		add(scroll, BorderLayout.CENTER);

		rebuild();
	}

	public void setActions(Runnable onCreate, Runnable onJoin,
		java.util.function.Consumer<String> onOpenGroup)
	{
		this.onCreate = onCreate;
		this.onJoin = onJoin;
		this.onOpenGroup = onOpenGroup;
	}

	/** Replaces what is on screen. One holder, so only one screen can ever be up. */
	public void show(JPanel screen)
	{
		content.removeAll();
		content.add(screen, BorderLayout.NORTH);
		content.revalidate();
		content.repaint();
	}

	/** Whether the front screen is the one showing, so a refresh knows not to trample a form. */
	public boolean isShowingList()
	{
		return content.getComponentCount() > 0 && content.getComponent(0) instanceof ListView;
	}

	/** Called whenever a drop lands, so the panel keeps up without anyone pressing anything. */
	public void refresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			// Only when the front screen is up. Rebuilding a half-filled form under someone's hands
			// would throw away what they had typed.
			if (isShowingList())
			{
				rebuild();
			}
		});
	}

	/** Back to the front screen, whatever was showing. */
	public void showList()
	{
		SwingUtilities.invokeLater(this::rebuild);
	}

	/** Marker so a refresh can tell which screen is up without tracking state separately. */
	private static class ListView extends JPanel
	{
	}

	private void rebuild()
	{
		ListView body = new ListView();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(Theme.BACKGROUND);

		body.add(Header.build("Your collection log, and how lucky you got"));

		body.add(Cards.gap(12));

		// The two things you can do, before anything you have. Someone opening this for the first time
		// should see the way in, not an empty list of their own drops.
		body.add(actions());

		body.add(Cards.gap(14));
		body.add(Cards.sectionLabel("Your groups"));
		body.add(Cards.gap(4));
		body.add(groups());

		body.add(Cards.gap(16));
		body.add(Cards.sectionLabel("Personal spoonage"));
		body.add(Cards.gap(4));
		body.add(summary());

		body.add(Cards.gap(12));
		body.add(spooniestToggle());

		if (spooniestOpen)
		{
			List<Spoon> luckiest = spoons.luckiestFirst();
			if (luckiest.isEmpty())
			{
				body.add(Cards.gap(4));
				body.add(Cards.muted(spoons.count() == 0
					? "Nothing yet. Go and fill a log slot and it will appear here."
					: "Nothing scored yet, the drops so far had no kill count to judge them on."));
			}

			for (Spoon spoon : luckiest)
			{
				body.add(Cards.gap(3));
				body.add(row(spoon));
			}
		}

		show(body);
	}

	/** Create and Join, side by side, because neither is the lesser of the two. */
	private JPanel actions()
	{
		JPanel row = new JPanel(new java.awt.GridLayout(1, 2, 8, 0));
		row.setBackground(Theme.BACKGROUND);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));

		// Called through rather than handed over. This panel is built by injection before the plugin
		// has said what the buttons do, so passing onCreate directly would hand each tile the empty
		// default and keep it for good, which is exactly what happened: two buttons that did nothing.
		row.add(new ActionTile("Create", () -> onCreate.run()));
		row.add(new ActionTile("Join", () -> onJoin.run()));

		return row;
	}

	/**
	 * The groups this account is in. More than one is normal, a clan and a group of mates are
	 * different competitions over the same collection log.
	 */
	private JPanel groups()
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(Theme.BACKGROUND);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);

		List<GroupStore.Membership> mine = groupStore.all();
		if (mine.isEmpty())
		{
			list.add(Cards.muted("None yet. Make one, or join with a code from a mate."));
			return list;
		}

		for (GroupStore.Membership membership : mine)
		{
			int members = membership.group.getMembers();
			list.add(new GroupCard(
				membership.group.getName(),
				members + (members == 1 ? " member" : " members"),
				() -> onOpenGroup.accept(membership.group.getCode())));
			list.add(Cards.gap(5));
		}

		return list;
	}

	/**
	 * "Your spooniest", which opens to show them.
	 * <p>
	 * Shut to begin with, because the front screen is a way in to two things and a list of forty
	 * drops between them buries both.
	 */
	private JPanel spooniestToggle()
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		JLabel label = new JLabel((spooniestOpen ? "− " : "+ ") + "Your spooniest");
		label.setFont(Theme.body());
		label.setForeground(Theme.TEXT_MUTED);
		row.add(label, BorderLayout.CENTER);

		int scored = spoons.luckiestFirst().size();
		JLabel count = new JLabel(scored == 0 ? "none yet" : String.valueOf(scored));
		count.setFont(Theme.body());
		count.setForeground(Theme.TEXT_MUTED);
		row.add(count, BorderLayout.EAST);

		row.addMouseListener(new java.awt.event.MouseAdapter()
		{
			// mousePressed rather than mouseClicked. Swing only fires a click when the press and the
			// release land on the same component with the mouse not having moved between them, so a
			// pixel of drift silently does nothing, which reads as the plugin ignoring you.
			@Override
			public void mousePressed(java.awt.event.MouseEvent event)
			{
				spooniestOpen = !spooniestOpen;
				rebuild();
			}
		});

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** The headline: how many log slots, and how many of them beat the drop rate. */
	private JPanel summary()
	{
		JPanel card = Cards.card();

		JLabel total = new JLabel(spoons.spoonCount() + " spooned");
		total.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 20f));
		total.setForeground(Theme.GOLD);
		total.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(total);

		card.add(Cards.gap(2));
		card.add(Cards.muted("out of " + spoons.count()
			+ (spoons.count() == 1 ? " log slot" : " log slots") + " since you installed this"));

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private JPanel row(Spoon spoon)
	{
		JPanel row = new JPanel(new BorderLayout(Cards.ROW_GAP, 0));
		row.setBackground(Theme.CARD);
		row.setBorder(BorderFactory.createEmptyBorder(Cards.ROW_PAD, Cards.ROW_PAD, Cards.ROW_PAD, Cards.ROW_PAD));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		row.add(icons.label(spoon.getItemId(), spoon.getItemName()), BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());

		// Wrapped: item names run to "Ancient ceremonial mask" and a plain label asks for the lot on
		// one line, which is enough to widen the whole sidebar.
		JLabel name = new JLabel(Cards.wrap(spoon.getItemName(), Cards.NAME_WRAP));
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(Theme.TEXT);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		String detail = spoon.getKillCount() > 0
			? "kc " + spoon.getKillCount() + " · 1 in " + Math.round(spoon.getDenominator())
			: spoon.getSource();
		text.add(Cards.mutedInRow(detail));
		text.add(Cards.mutedInRow(WHEN.format(new Date(spoon.getObtainedAt()))));

		row.add(text, BorderLayout.CENTER);

		// The luck reads as "top N%", the same wording the group already sees from Dink in Discord.
		JLabel luck = new JLabel(GroupView.percent(spoon.getShare()));
		luck.setFont(FontManager.getRunescapeBoldFont());
		luck.setForeground(colourFor(spoon.getShare()));
		row.add(luck, BorderLayout.EAST);

		Cards.fitRow(row);
		return row;
	}

	/**
	 * Gold for the genuinely absurd, down to muted for the ones that were merely on time. Colour rather
	 * than a number alone, so the good ones are findable without reading every row.
	 */
	private static Color colourFor(double share)
	{
		if (share < 0.05)
		{
			return Theme.GOLD;
		}

		if (share < 0.25)
		{
			return new Color(200, 200, 205);
		}

		if (share < 0.5)
		{
			return new Color(176, 122, 74);
		}

		return Theme.TEXT_MUTED;
	}
}

package com.spoon.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Image;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Gold, silver and bronze spoons for the top three.
 * <p>
 * The game's own wooden spoon, recoloured. Using the real item rather than something drawn is the
 * whole joke, it is a spoon that exists in Old School, and everyone knows what it means.
 * <p>
 * Filled in when the sprite arrives rather than asked for outright. {@link ItemManager#getImage}
 * hands back an image that is still empty and loads itself a moment later, so reading its pixels
 * straight away gives a blank, which is what an earlier version of this did, and then cached the
 * blank for good. Hence a label to fill rather than an icon to return.
 */
@Slf4j
@Singleton
public class Medals
{
	/** The wooden spoon, which is the only spoon Old School has. */
	private static final int WOODEN_SPOON = 7433;

	private static final int SIZE = 22;

	private static final Color[] COLOURS = {
		new Color(255, 196, 70),
		new Color(214, 216, 224),
		new Color(196, 132, 76)
	};

	private final ItemManager itemManager;

	/** Kept once made, since the same three spoons are drawn on every screen. */
	private final ImageIcon[] cache = new ImageIcon[3];

	@Inject
	private Medals(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * A label carrying the spoon for a place, filled now or as soon as the sprite loads.
	 *
	 * @param place 1, 2 or 3
	 */
	public JLabel label(int place)
	{
		JLabel label = new JLabel();

		// Sized up front so the row does not jump when the sprite arrives a moment later.
		label.setPreferredSize(new Dimension(SIZE, SIZE));

		if (place < 1 || place > 3)
		{
			return label;
		}

		ImageIcon ready = cache[place - 1];
		if (ready != null)
		{
			label.setIcon(ready);
			return label;
		}

		try
		{
			AsyncBufferedImage sprite = itemManager.getImage(WOODEN_SPOON);
			if (sprite != null)
			{
				sprite.onLoaded(() -> fill(label, sprite, place));
			}
		}
		catch (RuntimeException e)
		{
			// A missing medal costs a bit of fun; it must never stop the leaderboard being drawn.
			log.debug("Could not make a medal for place {}", place, e);
		}

		return label;
	}

	private void fill(JLabel label, BufferedImage sprite, int place)
	{
		ImageIcon icon = cache[place - 1];

		if (icon == null)
		{
			try
			{
				BufferedImage tinted = SpoonIcon.tint(sprite, COLOURS[place - 1]);
				icon = new ImageIcon(tinted.getScaledInstance(SIZE, SIZE, Image.SCALE_SMOOTH));
				cache[place - 1] = icon;
			}
			catch (RuntimeException e)
			{
				log.debug("Could not tint the spoon for place {}", place, e);
				return;
			}
		}

		ImageIcon ready = icon;
		SwingUtilities.invokeLater(() ->
		{
			label.setIcon(ready);
			label.revalidate();
			label.repaint();
		});
	}
}

