/**
 * Claiming a drop the plugin never saw.
 * <p>
 * Everything except the item is optional, because a drop from three years ago is remembered in
 * pieces. A claim with no kill count still belongs on the board once the group agrees; it simply
 * cannot be scored, and the voting screen says so.
 */
public class ClaimPanel extends JPanel
{
	public ClaimPanel(Consumer<Claim> onSubmit, Runnable onBack)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(Theme.BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(4, 0, 8, Cards.SCROLLBAR_ALLOWANCE));

		add(Header.build("Claim a drop"));
		add(Cards.gap(10));
		add(Cards.muted("For something you got before this plugin was watching. The rest of the group "
			+ "votes on it, and more than half of them have to believe you."));

		add(Cards.gap(12));
		JTextField item = field("Item");
		JTextField source = field("Where from");
		JTextField killCount = field("Kill count");
		JTextField evidence = field("Link to a screenshot");
		JTextField note = field("Anything to add");

		add(Cards.gap(14));
		add(new ActionTile("Put it to the group", () ->
		{
			String name = item.getText().trim();
			if (name.isEmpty())
			{
				Cards.warn(this, "Which item?");
				return;
			}

			Claim claim = new Claim();
			claim.setItemName(name);
			claim.setSource(source.getText().trim());
			claim.setEvidence(evidence.getText().trim());
			claim.setNote(note.getText().trim());

			String kc = killCount.getText().trim();
			if (!kc.isEmpty())
			{
				try
				{
					claim.setKillCount(Integer.valueOf(kc));
				}
				catch (NumberFormatException e)
				{
					Cards.warn(this, "\"" + kc + "\" is not a kill count.");
					return;
				}
			}

			onSubmit.accept(claim);
		}));

		add(Cards.gap(8));
		add(Cards.muted("Only the item is needed. Without a kill count it can still go on the board, "
			+ "but it can never be scored."));

		add(Cards.gap(12));
		JButton back = Cards.button("← Back");
		back.setAlignmentX(Component.LEFT_ALIGNMENT);
		back.addActionListener(event -> onBack.run());
		add(back);

		SwingUtilities.invokeLater(item::requestFocusInWindow);
	}

	private JTextField field(String label)
	{
		add(Cards.sectionLabel(label));
		add(Cards.gap(2));

		JTextField field = Theme.textField(new JTextField());
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		field.setFont(Theme.body());
		add(field);
		add(Cards.gap(8));

		return field;
	}
}

package com.spoon.ui;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/**
 * A spoon, drawn.
 * <p>
 * Drawn rather than taken from the game because this is a logo rather than an item: it has to stay
 * crisp at whatever size a heading needs, and be the colour of the heading beside it. The real
 * article, the wooden spoon, is used where an item is actually meant, on the leaderboard.
 */
public final class SpoonIcon
{
	private SpoonIcon()
	{
	}

	/**
	 * @param size   the square to draw within
	 * @param body   the metal
	 * @param hollow the inside of the bowl, which is what stops it reading as a flat blob
	 */
	public static BufferedImage draw(int size, Color body, Color hollow)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = Theme.smooth(image.createGraphics());

		// Tilted, because a spoon standing to attention looks like a lollipop. Leaning right, so the
		// bowl points away from the title rather than back into it.
		graphics.rotate(Math.toRadians(30), size / 2.0, size / 2.0);

		// A narrow, tall bowl. Anything close to a circle reads as a magnifying glass, which is what
		// the first attempt at this looked like.
		double bowlWidth = size * 0.34;
		double bowlHeight = size * 0.46;
		double bowlX = (size - bowlWidth) / 2.0;
		double bowlY = size * 0.05;

		// The handle is drawn first and long, so the shape is mostly stem, which is what says spoon.
		double handleWidth = Math.max(1.6, size * 0.10);
		graphics.setColor(body);
		graphics.fill(new RoundRectangle2D.Double(
			(size - handleWidth) / 2.0,
			bowlY + bowlHeight * 0.72,
			handleWidth,
			size * 0.60,
			handleWidth,
			handleWidth));

		graphics.fill(new Ellipse2D.Double(bowlX, bowlY, bowlWidth, bowlHeight));

		// The hollow is filled rather than outlined: a ring around the bowl is exactly what made the
		// first version look like a lens.
		double inset = Math.max(1.0, size * 0.06);
		graphics.setColor(hollow);
		graphics.fill(new Ellipse2D.Double(
			bowlX + inset,
			bowlY + inset,
			bowlWidth - inset * 2,
			bowlHeight - inset * 2.4));

		graphics.dispose();
		return image;
	}

	/** The logo beside the title: gold, with a warmer highlight. */
	public static BufferedImage logo(int size)
	{
		return draw(size, Theme.GOLD, new Color(255, 228, 170));
	}

	/**
	 * Turns the game's own wooden spoon into a medal.
	 * <p>
	 * Taken to grey first and then tinted, rather than shifted in hue, so a brown sprite comes out as
	 * clean gold or silver instead of a muddier brown.
	 */
	public static BufferedImage tint(BufferedImage source, Color colour)
	{
		BufferedImage out = new BufferedImage(
			source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);

		for (int y = 0; y < source.getHeight(); y++)
		{
			for (int x = 0; x < source.getWidth(); x++)
			{
				int argb = source.getRGB(x, y);
				int alpha = (argb >>> 24) & 0xFF;

				if (alpha == 0)
				{
					continue;
				}

				int red = (argb >> 16) & 0xFF;
				int green = (argb >> 8) & 0xFF;
				int blue = argb & 0xFF;

				// Perceptual weights, so the sprite's shading survives the trip to grey.
				double luma = (0.299 * red + 0.587 * green + 0.114 * blue) / 255.0;

				int r = clamp(colour.getRed() * luma);
				int g = clamp(colour.getGreen() * luma);
				int b = clamp(colour.getBlue() * luma);

				out.setRGB(x, y, (alpha << 24) | (r << 16) | (g << 8) | b);
			}
		}

		return out;
	}

	private static int clamp(double value)
	{
		return Math.max(0, Math.min(255, (int) Math.round(value)));
	}
}

package com.spoon.ui;

import com.spoon.data.Claim;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * Drops the group is still voting on.
 * <p>
 * Kept apart from the leaderboard on purpose. Nothing here counts for anything yet, and a claim
 * sitting among real drops would look like one.
 */
public class ClaimsPanel extends JPanel
{
	private final BiConsumer<String, Boolean> onVote;
	private final Consumer<String> onOpenEvidence;

	public ClaimsPanel(BiConsumer<String, Boolean> onVote, Consumer<String> onOpenEvidence)
	{
		this.onVote = onVote;
		this.onOpenEvidence = onOpenEvidence;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(Theme.BACKGROUND);
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	public void show(List<Claim> claims)
	{
		removeAll();

		if (claims.isEmpty())
		{
			add(Cards.muted("Nothing waiting on a vote."));
		}

		for (Claim claim : claims)
		{
			add(row(claim));
			add(Cards.gap(3));
		}

		revalidate();
		repaint();
	}

	public void showMessage(String message)
	{
		removeAll();
		add(Cards.muted(message));
		revalidate();
		repaint();
	}

	private JPanel row(Claim claim)
	{
		JPanel card = Cards.card();

		JLabel who = new JLabel(Cards.wrap(claim.getRsn() + " says they got", 150));
		who.setFont(Theme.body());
		who.setForeground(Theme.TEXT_MUTED);
		who.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(who);

		JLabel item = new JLabel(Cards.wrap(claim.getItemName(), 150));
		item.setFont(FontManager.getRunescapeBoldFont());
		item.setForeground(Theme.GOLD);
		item.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(item);

		StringBuilder detail = new StringBuilder();
		if (claim.getKillCount() != null)
		{
			detail.append("kc ").append(claim.getKillCount());
		}
		else
		{
			// Said plainly. A claim with no kill count can be voted onto the board and can never be
			// scored, and somebody voting on it should know that before they do.
			detail.append("no kill count given");
		}

		if (claim.getSource() != null && !claim.getSource().isEmpty())
		{
			detail.append(" · ").append(claim.getSource());
		}

		card.add(Cards.gap(1));
		card.add(Cards.mutedInRow(detail.toString()));

		if (claim.getNote() != null && !claim.getNote().isEmpty())
		{
			card.add(Cards.gap(2));
			card.add(Cards.muted("“" + claim.getNote() + "”"));
		}

		card.add(Cards.gap(4));
		card.add(Cards.mutedInRow(claim.getApprovals() + " of " + claim.getNeeded() + " needed"
			+ (claim.getRejections() > 0 ? " · " + claim.getRejections() + " against" : "")));

		if (claim.getEvidence() != null && !claim.getEvidence().isEmpty())
		{
			card.add(Cards.gap(4));
			JButton evidence = Cards.button("Open the screenshot");
			evidence.setAlignmentX(Component.LEFT_ALIGNMENT);
			evidence.addActionListener(event -> onOpenEvidence.accept(claim.getEvidence()));
			card.add(evidence);
		}

		card.add(Cards.gap(4));
		card.add(voteRow(claim));

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private JPanel voteRow(Claim claim)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(Theme.CARD);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (claim.isYours())
		{
			// Nobody carries their own claim, which is the point of putting it to the group.
			JLabel yours = new JLabel("Yours, waiting on the others");
			yours.setFont(Theme.body());
			yours.setForeground(Theme.TEXT_MUTED);
			row.add(yours, BorderLayout.CENTER);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
			return row;
		}

		JPanel buttons = new JPanel(new java.awt.GridLayout(1, 2, 4, 0));
		buttons.setBackground(Theme.CARD);

		JButton yes = Cards.button(Boolean.TRUE.equals(claim.getYourVote()) ? "Believed ✓" : "Believe");
		yes.addActionListener(event -> onVote.accept(claim.getId(), true));
		buttons.add(yes);

		JButton no = Cards.button(Boolean.FALSE.equals(claim.getYourVote()) ? "Doubted ✓" : "Doubt");
		no.addActionListener(event -> onVote.accept(claim.getId(), false));
		buttons.add(no);

		row.add(buttons, BorderLayout.CENTER);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		return row;
	}
}

