package com.spoon.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * How rare each thing is, by the monster that drops it.
 * <p>
 * Bundled rather than fetched, so the plugin never calls out to the wiki while someone is playing and
 * a drop can always be scored the instant it lands. The file is Dink's, used under its BSD licence and
 * credited in NOTICE.md, see there for why sharing its data matters rather than rebuilding it.
 */
@Slf4j
@Singleton
public class DropRates
{
	/** One item as the dataset stores it: {@code i} the item id, {@code d} the "1 in d". */
	private static class Entry
	{
		int i;
		double d;
	}

	private final Map<String, List<Entry>> bySource;

	@Inject
	private DropRates(Gson gson)
	{
		Map<String, List<Entry>> loaded = new java.util.HashMap<>(read(gson, "/com/spoon/npc-drops.json"));

		// Laid over the top rather than merged into the file itself. Dink's data is theirs, kept as
		// they published it, and what is missing from it is a separate thing that can be rebuilt on
		// its own. Grotesque Guardians is the reason it exists: a boss its data has never had, whose
		// drops sat unscored while the wiki stated their odds plainly.
		loaded.putAll(read(gson, "/com/spoon/extra-drops.json"));

		this.bySource = loaded;
		log.debug("Loaded drop rates for {} sources", bySource.size());
	}

	private static Map<String, List<Entry>> read(Gson gson, String resource)
	{
		Type type = new TypeToken<Map<String, List<Entry>>>()
		{
		}.getType();

		try (InputStream in = DropRates.class.getResourceAsStream(resource))
		{
			if (in == null)
			{
				// The wiki data is optional and generated, so a build without it is a normal build.
				log.debug("No drop rate data at {}", resource);
				return Collections.emptyMap();
			}

			Map<String, List<Entry>> loaded =
				gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);

			return loaded == null ? Collections.emptyMap() : loaded;
		}
		catch (Exception e)
		{
			// Never fatal. Without rates, drops are still recorded, they simply cannot be scored, which
			// is a worse plugin rather than a broken one.
			log.warn("Could not read the drop rate data at {}", resource, e);
			return Collections.emptyMap();
		}
	}

	/** One thing a monster drops: which item, and the "1 in N" of getting it. */
	public static final class Drop
	{
		public final int itemId;
		public final double denominator;

		Drop(int itemId, double denominator)
		{
			this.itemId = itemId;
			this.denominator = denominator;
		}
	}

	/**
	 * Everything a monster drops.
	 * <p>
	 * Exposed so a drop can be identified by name against this list rather than by asking RuneLite to
	 * look the name up. {@code ItemManager.search} answers from the price API, which only knows
	 * tradeable items, so it finds nothing for pets, and pets are the entire point of a plugin about
	 * being spooned. Matching against a monster's own drop list has no such gap, and it is a few dozen
	 * items rather than the whole game.
	 */
	public List<Drop> dropsFrom(String source)
	{
		if (source == null)
		{
			return Collections.emptyList();
		}

		List<Entry> entries = bySource.get(source);
		if (entries == null)
		{
			entries = findIgnoringCase(source);
		}

		if (entries == null)
		{
			return Collections.emptyList();
		}

		List<Drop> drops = new java.util.ArrayList<>(entries.size());
		for (Entry entry : entries)
		{
			drops.add(new Drop(entry.i, entry.d));
		}

		return drops;
	}

	/**
	 * The "1 in N" for an item from a given monster.
	 *
	 * @return the denominator, or -1 when this source is not in the data or never drops that item
	 */
	public double denominatorFor(String source, int itemId)
	{
		if (source == null)
		{
			return -1;
		}

		List<Entry> entries = bySource.get(source);
		if (entries == null)
		{
			// Names come from the game and the dataset was built from the wiki, so they mostly agree but
			// not always. A case-insensitive sweep costs one pass and rescues the ones that differ only
			// in capitalisation.
			entries = findIgnoringCase(source);
		}

		if (entries == null)
		{
			return -1;
		}

		for (Entry entry : entries)
		{
			if (entry.i == itemId)
			{
				return entry.d;
			}
		}

		return -1;
	}

	private List<Entry> findIgnoringCase(String source)
	{
		String wanted = source.toLowerCase(Locale.ROOT);
		for (Map.Entry<String, List<Entry>> candidate : bySource.entrySet())
		{
			if (candidate.getKey().toLowerCase(Locale.ROOT).equals(wanted))
			{
				return candidate.getValue();
			}
		}

		return null;
	}

	/** Every monster the data knows, so the whole set of dropped items can be walked once. */
	public java.util.Set<String> sources()
	{
		return bySource.keySet();
	}

	public boolean isEmpty()
	{
		return bySource.isEmpty();
	}
}

package com.spoon.data;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One collection log item, and how lucky getting it was.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Spoon
{
	/**
	 * Made here and kept for good, so the service can tell a resend from a second drop. Without it a
	 * batch sent twice after a timeout would count twice.
	 */
	private String id = java.util.UUID.randomUUID().toString();

	private String itemName = "";
	private int itemId;

	/** The monster it came off, as the game named it. Empty when nothing could be attributed. */
	private String source = "";

	/** The kill count it landed on, or -1 when nothing knew it. */
	private int killCount = -1;

	/** The "1 in N", or -1 when the item is not in the drop data. */
	private double denominator = -1;

	/**
	 * The share of players who would already have this by that kill count. Low is lucky. -1 when it
	 * could not be worked out, which is not the same as unlucky and must never be sorted as though it
	 * were.
	 */
	private double share = -1;

	private long obtainedAt;

	/** Typed in by the player rather than seen happening, and shown as such. */
	private boolean claimed;

	public boolean isScored()
	{
		return share >= 0;
	}
}

package com.spoon.data;

/**
 * How lucky a drop was, on a scale everyone can be compared on.
 * <p>
 * A raw kill count says nothing on its own, ten kills for a 1/128 is unremarkable, ten kills for a
 * 1/5000 is a story. What matters is how you did against the people who went for the same thing.
 * <p>
 * So a drop is scored by the share of players who would already have had it by the kill count you got
 * it on. Getting an item at the point where only 3% of people have it makes you spoonier than 97% of
 * the accounts that chased it, whatever the rate happens to be. That puts a pet and a clue item on one
 * scale, which is the only way a leaderboard across different bosses means anything.
 * <p>
 * This is the same figure Dink puts in its Discord messages, deliberately: a group that has been
 * reading "Top 40% (Lucky)" for months should not be told a different number by this.
 */
public final class Luck
{
	private Luck()
	{
	}

	/**
	 * The share of players who would already hold this item by the given kill count.
	 * <p>
	 * Low is lucky. A result of 0.03 means you got it while 97% of people were still going.
	 *
	 * @param denominator the "1 in N" of the drop
	 * @param killCount   the kill count it landed on
	 * @return between 0 and 1, or -1 when it cannot be worked out
	 */
	public static double shareWhoHaveItBy(double denominator, int killCount)
	{
		if (denominator <= 0 || killCount <= 0)
		{
			// No rate for this item, or no kill count recorded against it. Both happen, a clue scroll
			// item has no source to count kills of, and neither can be scored.
			return -1;
		}

		double perKill = 1.0 / denominator;

		// 1 - (1-p)^n, the chance of at least one success in n attempts. Worked out through logs rather
		// than Math.pow so that the very long odds people actually care about, a 1 in 5000 pet over
		// thousands of kills, do not lose their precision.
		return -Math.expm1(killCount * Math.log1p(-perKill));
	}

	/** Whether a drop counts as spooned: it came before most people would have had it. */
	public static boolean isSpooned(double share)
	{
		return share >= 0 && share < 0.5;
	}
}

package com.spoon.data;

import lombok.Data;
import lombok.NoArgsConstructor;

/**
