package com.spoon.net;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.spoon.data.Claim;
import com.spoon.data.Group;
import com.spoon.data.Holder;
import com.spoon.data.Standing;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the service groups share.
 * <p>
 * Every call returns either what was asked for or why not, and never throws at the caller. A panel
 * that has to catch exceptions to show a message ends up showing stack traces to players.
 */
@Slf4j
@Singleton
public class SpoonApi
{
	private static final MediaType JSON = MediaType.get("application/json");

	private final OkHttpClient httpClient;

	/**
	 * The client for reading Discord history, which is the one call here allowed to take a while.
	 * <p>
	 * RuneLite's shared client carries OkHttp's default ten second read timeout. That is right for
	 * every other call in this file and wrong for this one: the service is reading somebody's Discord
	 * channel, and a chunk of it that takes eleven seconds is not a service that has died. Everything
	 * else, the connection pool included, is still shared.
	 */
	private final OkHttpClient importClient;

	private final Gson gson;

	@Inject
	private SpoonApi(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.importClient = httpClient.newBuilder()
			.readTimeout(30, TimeUnit.SECONDS)
			.build();
		this.gson = gson;
	}

	/** Either what was asked for, or why not. */
	@Value
	public static class Result<T>
	{
		T value;
		String error;

		/**
		 * The service answered and said there is no such group.
		 * <p>
		 * Kept apart from every other failure because they call for opposite responses: a group that is
		 * gone should come off the list, while one that merely could not be reached must be left alone.
		 * Treating the second as the first would delete somebody's group because their wifi dropped.
		 */
		boolean gone;

		public boolean ok()
		{
			return error == null;
		}

		static <T> Result<T> of(T value)
		{
			return new Result<>(value, null, false);
		}

		static <T> Result<T> failed(String error)
		{
			return new Result<>(null, error, false);
		}

		static <T> Result<T> gone(String error)
		{
			return new Result<>(null, error, true);
		}
	}

	/** A group and its leaderboard, which always travel together. */
	@Value
	public static class Snapshot
	{
		Group group;
		List<Standing> leaderboard;

		/** Only present when the group was just created or joined. */
		String creatorToken;
		String memberToken;
	}

	public Result<Snapshot> create(String baseUrl, String name, String creatorRsn)
	{
		JsonObject body = new JsonObject();
		body.addProperty("name", name);
		body.addProperty("creatorRsn", creatorRsn);

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "groups"))
			.post(RequestBody.create(JSON, gson.toJson(body))));
	}

	public Result<Snapshot> read(String baseUrl, String code)
	{
		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code))
			.get());
	}

	public Result<Snapshot> join(String baseUrl, String code, String rsn)
	{
		JsonObject body = new JsonObject();
		body.addProperty("rsn", rsn);

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code, "join"))
			.post(RequestBody.create(JSON, gson.toJson(body))));
	}

	public Result<Snapshot> delete(String baseUrl, String code, String creatorToken)
	{
		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code))
			.delete()
			.header("X-Creator-Token", creatorToken));
	}

	/**
	 * Sends drops. Each keeps its id, so a batch sent twice counts once.
	 */
	public Result<Snapshot> submit(String baseUrl, String code, String memberToken, Object drops)
	{
		JsonObject body = new JsonObject();
		body.add("drops", gson.toJsonTree(drops));

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code, "drops"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Member-Token", memberToken));
	}

	/**
	 * How many chunks one press may read, against a service that never says it has finished.
	 *
	 * Four hundred of them is the best part of a million messages, which no clan has, so reaching
	 * this means something has gone wrong rather than that somebody talks a lot.
	 */
	private static final int CHUNK_LIMIT = 400;

	/**
	 * Reads the group's linked Discord channel to its end, and adds up what was in it.
	 *
	 * The service answers a chunk at a time, because reading a clan's whole history into one answer
	 * takes longer than this plugin waits for one, and more of a Worker's allowance than it is given.
	 * That is a fact about the asking rather than about the importing, so it is kept in here: one call
	 * still reads the whole channel.
	 *
	 * @param dryRun   report what would happen without doing it, which is what the plugin shows first
	 * @param progress given the running totals after each chunk, so that a long read can say how it is
	 *                 getting on instead of sitting there silently
	 */
	public Result<Import> importFromDiscord(
		String baseUrl, String code, String creatorToken, boolean dryRun, Consumer<Import> progress)
	{
		return readChannel(dryRun, progress,
			cursor -> importChunk(baseUrl, code, creatorToken, dryRun, cursor));
	}

	/**
	 * The reading itself, told only how to ask for one chunk.
	 *
	 * Kept apart from what it is asking so that carrying on, adding up and giving up can be tried
	 * without a Discord, a service or a network behind them.
	 */
	static Result<Import> readChannel(
		boolean dryRun, Consumer<Import> progress, Function<String, Result<Import>> read)
	{
		Import total = new Import();
		String cursor = null;

		for (int chunk = 0; chunk < CHUNK_LIMIT; chunk++)
		{
			Result<Import> result = read.apply(cursor);

			if (!result.ok())
			{
				// Nothing already brought in is lost by stopping here. Drops are keyed on Discord's own
				// message ids, so going again reads what this run did not, rather than a second copy of
				// what it did.
				return chunk == 0
					? result
					: Result.failed(stoppedEarly(total, dryRun, result.getError()));
			}

			Import part = result.getValue();

			// No bot in the server is the step before this one, and it is the whole answer.
			if (part == null || part.isNeedsBot())
			{
				return result;
			}

			add(total, part);

			if (progress != null)
			{
				progress.accept(total);
			}

			cursor = part.getCursor();

			// A service that hands back no cursor read the channel in one go, which is also what an
			// older one that has never heard of chunks does.
			if (part.isDone() || cursor == null)
			{
				break;
			}
		}

		return Result.of(total);
	}

	/** What each chunk adds to the running totals. */
	private static void add(Import total, Import part)
	{
		total.setFound(total.getFound() + part.getFound());
		total.setSkipped(total.getSkipped() + part.getSkipped());
		total.setMatched(total.getMatched() + part.getMatched());
		total.setImported(total.getImported() + part.getImported());
		total.setWithoutKillCount(total.getWithoutKillCount() + part.getWithoutKillCount());
		total.setWithoutRate(total.getWithoutRate() + part.getWithoutRate());
		total.setDone(part.isDone());
		total.setCursor(part.getCursor());

		if (part.getUnmatched() == null)
		{
			return;
		}

		for (java.util.Map.Entry<String, Integer> entry : part.getUnmatched().entrySet())
		{
			total.getUnmatched().merge(entry.getKey(), entry.getValue(), Integer::sum);
		}
	}

	/**
	 * Said when a read gives out partway through a channel.
	 *
	 * What it managed is worth saying. Half a clan's history is not nothing, and the difference
	 * between "that failed" and "that got four hundred in, go again for the rest" is the difference
	 * between somebody giving up on it and somebody pressing the button.
	 */
	private static String stoppedEarly(Import total, boolean dryRun, String error)
	{
		String far = dryRun
			? "Read " + String.format("%,d", total.getFound() + total.getSkipped()) + " messages"
			: "Brought in " + String.format("%,d", total.getImported()) + " drops";

		return far + ", then stopped: " + error + System.lineSeparator()
			+ "Look for history again to bring in the rest. Nothing already in is brought in twice.";
	}

	/**
	 * One chunk of it.
	 *
	 * @param cursor where the last chunk stopped, or null to start at the newest message
	 */
	private Result<Import> importChunk(
		String baseUrl, String code, String creatorToken, boolean dryRun, String cursor)
	{
		JsonObject body = new JsonObject();
		body.addProperty("dryRun", dryRun);

		// Says this plugin holds its own place in the channel, so the service does not keep one for it.
		body.addProperty("paged", true);

		if (cursor != null)
		{
			body.addProperty("cursor", cursor);
		}

		Request request = new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code, "import"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Creator-Token", creatorToken)
			.build();

		try (Response response = importClient.newCall(request).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				// A group with no bot in its server is not a failure, it is the step before this one, and
				// the answer carries what is needed to take it. Handed back as a result so the plugin can
				// offer the invite rather than print a message telling someone to go and find it.
				if (response.code() == 409)
				{
					Import needsBot = gson.fromJson(text, Import.class);
					if (needsBot != null && needsBot.isNeedsBot())
					{
						return Result.of(needsBot);
					}
				}

				return Result.failed(messageIn(text, "Could not import"));
			}

			return Result.of(gson.fromJson(text, Import.class));
		}
		catch (IOException e)
		{
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException e)
		{
			return Result.failed("The server sent something unreadable");
		}
	}

	/** What an import found, or would find. */
	@lombok.Data
	public static class Import
	{
		/** Collection log messages seen in the channel. */
		private int found;

		/** Messages that were not collection log notifications at all. */
		private int skipped;

		/** Of those found, how many belong to somebody in this group. */
		private int matched;

		private int imported;

		/** Drops with no kill count recorded, which can be kept but never scored. */
		private int withoutKillCount;

		/** And drops whose kill count is known but whose odds are not, which is a different hole. */
		private int withoutRate;

		/** Names seen in the channel that are not in this group, and how many drops each had. */
		private java.util.Map<String, Integer> unmatched = new java.util.LinkedHashMap<>();

		/** There is no bot in the group's Discord server yet, so there is nothing to read. */
		private boolean needsBot;

		/** Where to send someone to put that right. */
		private String invite;

		/** What to type once the bot is in, with the group's own code already in it. */
		private String linkCommand;

		/** Where this chunk of the channel stopped, to be handed back to carry on from there. */
		private String cursor;

		/** Whether the channel has been read all the way to its end. */
		private boolean done;
	}

	/**
	 * Puts a drop to the group that the plugin never saw.
	 */
	public Result<List<Claim>> claim(
		String baseUrl, String code, String memberToken, Claim claim)
	{
		JsonObject body = new JsonObject();
		body.addProperty("itemName", claim.getItemName());
		body.addProperty("itemId", claim.getItemId());

		if (claim.getSource() != null)
		{
			body.addProperty("source", claim.getSource());
		}

		if (claim.getKillCount() != null)
		{
			body.addProperty("killCount", claim.getKillCount());
		}

		if (claim.getDenominator() != null)
		{
			body.addProperty("denominator", claim.getDenominator());
		}

		if (claim.getEvidence() != null && !claim.getEvidence().isEmpty())
		{
			body.addProperty("evidence", claim.getEvidence());
		}

		if (claim.getNote() != null && !claim.getNote().isEmpty())
		{
			body.addProperty("note", claim.getNote());
		}

		Request request = new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code, "claims"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Member-Token", memberToken)
			.build();

		return readList(request, "claims", new TypeToken<List<Claim>>()
		{
		}.getType(), "Could not put that to the group");
	}

	/** Everything the group is still voting on. */
	public Result<List<Claim>> claims(String baseUrl, String code, String memberToken)
	{
		Request request = new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code, "claims"))
			.get()
			.header("X-Member-Token", memberToken)
			.build();

		return readList(request, "claims", new TypeToken<List<Claim>>()
		{
		}.getType(), "Could not load the claims");
	}

	/**
	 * A yes or a no.
	 *
	 * @return what it settled as, or null if it is still waiting on other people
	 */
	public Result<String> vote(
		String baseUrl, String code, String memberToken, String claimId, boolean approve)
	{
		JsonObject body = new JsonObject();
		body.addProperty("approve", approve);

		Request request = new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code, "claims", claimId, "vote"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Member-Token", memberToken)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				return Result.failed(messageIn(text, "Could not vote"));
			}

			JsonObject root = gson.fromJson(text, JsonObject.class);
			return Result.of(root != null && root.has("settled") && !root.get("settled").isJsonNull()
				? root.get("settled").getAsString()
				: null);
		}
		catch (IOException e)
		{
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException e)
		{
			return Result.failed("The server sent something unreadable");
		}
	}

	/**
	 * One member's drops, for looking at somebody's luck on its own.
	 *
	 * @param sort "recent" or "luck"
	 */
	public Result<MemberDrops> memberDrops(String baseUrl, String code, String rsn, String sort)
	{
		HttpUrl url = url(baseUrl, "v1", "groups", code, "members", rsn, "drops")
			.newBuilder()
			.addQueryParameter("sort", sort)
			.build();

		Request request = new Request.Builder().url(url).get().build();

		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				String message = messageIn(text, "Could not load those drops");
				return response.code() == 404 ? Result.gone(message) : Result.failed(message);
			}

			return Result.of(gson.fromJson(text, MemberDrops.class));
		}
		catch (IOException e)
		{
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException e)
		{
			return Result.failed("The server sent something unreadable");
		}
	}

	/** One member, their totals, and their drops in the order asked for. */
	@lombok.Data
	public static class MemberDrops
	{
		private String rsn = "";
		private int spoons;
		private int scored;
		private double avgShare = 0.5;
		private String sort = "recent";
		private List<Holder> drops = new ArrayList<>();
	}

	/** Everyone in the group who has one item, luckiest first. The question this is all named after. */
	public Result<List<Holder>> whoSpoonedIt(String baseUrl, String code, String itemName)
	{
		Request request = new Request.Builder()
			.url(url(baseUrl, "v1", "groups", code, "items", itemName))
			.get()
			.build();

		return readList(request, "holders", new TypeToken<List<Holder>>()
		{
		}.getType(), "Could not look that item up");
	}

	/** Item names anyone in the group has, for the search box to offer. */
	public Result<List<Holder>> search(String baseUrl, String code, String query)
	{
		HttpUrl url = url(baseUrl, "v1", "groups", code, "search")
			.newBuilder()
			.addQueryParameter("q", query)
			.build();

		return readList(new Request.Builder().url(url).get().build(),
			"items", new TypeToken<List<Holder>>()
			{
			}.getType(), "Could not search");
	}

	private <T> Result<List<T>> readList(Request request, String field, Type type, String fallback)
	{
		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				String message = messageIn(text, fallback);
				return response.code() == 404 ? Result.gone(message) : Result.failed(message);
			}

			JsonObject root = gson.fromJson(text, JsonObject.class);
			List<T> parsed = root != null && root.has(field)
				? gson.fromJson(root.get(field), type)
				: new ArrayList<>();

			return Result.of(parsed == null ? new ArrayList<>() : parsed);
		}
		catch (IOException e)
		{
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException e)
		{
			return Result.failed("The server sent something unreadable");
		}
	}

	private Result<Snapshot> send(Request.Builder builder)
	{
		try (Response response = httpClient.newCall(builder.build()).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				String message = messageIn(text, "The server said no (" + response.code() + ")");
				return response.code() == 404 ? Result.gone(message) : Result.failed(message);
			}

			return Result.of(parse(text));
		}
		catch (IOException e)
		{
			log.debug("Request failed", e);
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Unreadable response", e);
			return Result.failed("The server sent something unreadable");
		}
	}

	private Snapshot parse(String text)
	{
		JsonObject root = gson.fromJson(text, JsonObject.class);
		if (root == null)
		{
			return new Snapshot(null, new ArrayList<>(), null, null);
		}

		Group group = root.has("group") && !root.get("group").isJsonNull()
			? gson.fromJson(root.get("group"), Group.class)
			: null;

		List<Standing> leaderboard = new ArrayList<>();
		if (root.has("leaderboard") && root.get("leaderboard").isJsonArray())
		{
			Type type = new TypeToken<List<Standing>>()
			{
			}.getType();

			List<Standing> parsed = gson.fromJson(root.get("leaderboard"), type);
			if (parsed != null)
			{
				leaderboard.addAll(parsed);
			}
		}

		// The code comes back at the top level on create, where the group does not carry it yet.
		if (group != null && (group.getCode() == null || group.getCode().isEmpty()) && root.has("code"))
		{
			group.setCode(root.get("code").getAsString());
		}

		return new Snapshot(
			group,
			leaderboard,
			stringOrNull(root, "creatorToken"),
			stringOrNull(root, "memberToken"));
	}

	/**
	 * The server's own wording where there is one. It says "No group with that code", which is more use
	 * to a player than anything this class could invent.
	 */
	private String messageIn(String text, String fallback)
	{
		try
		{
			JsonObject root = gson.fromJson(text, JsonObject.class);
			if (root != null && root.has("error"))
			{
				return root.get("error").getAsString();
			}
		}
		catch (JsonSyntaxException ignored)
		{
			// Fall through to the generic message.
		}

		return fallback;
	}

	private static String stringOrNull(JsonObject root, String key)
	{
		return root.has(key) && !root.get(key).isJsonNull() ? root.get(key).getAsString() : null;
	}

	private static HttpUrl url(String baseUrl, String... segments)
	{
		HttpUrl parsed = HttpUrl.parse(baseUrl.trim());
		if (parsed == null)
		{
			throw new IllegalArgumentException("The server address is not a valid URL: " + baseUrl);
		}

		HttpUrl.Builder builder = parsed.newBuilder();
		for (String segment : segments)
		{
			builder.addPathSegment(segment);
		}

		return builder.build();
	}
}

package com.spoon;

import com.google.inject.Provides;
import com.spoon.data.Luck;
import com.spoon.data.Spoon;
import com.spoon.track.ClogWatcher;
import com.spoon.track.DropSender;
import com.spoon.track.GroupStore;
import com.spoon.track.SpoonStore;
import com.spoon.net.SpoonApi;
import com.spoon.ui.CreateGroupPanel;
import com.spoon.ui.ClaimPanel;
import com.spoon.ui.ClaimsPanel;
import com.spoon.ui.GroupView;
import com.spoon.ui.ItemIcons;
import com.spoon.ui.MemberView;
import com.spoon.ui.JoinGroupPanel;
import com.spoon.ui.Medals;
import com.spoon.ui.SpoonPanel;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Who Spooned It?",
	description = "Records how lucky each collection log drop was, and compares it with your group",
	tags = {"collection", "log", "clog", "luck", "drop", "rate", "spoon", "group"}
)
public class WhoSpoonedItPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private ClogWatcher watcher;

	@Inject
	private SpoonStore spoons;

	@Inject
	private GroupStore groups;

	@Inject
	private SpoonPanel panel;

	@Inject
	private DropSender sender;

	@Inject
	private com.spoon.data.DropRates dropRates;

	@Inject
	private net.runelite.client.game.ItemManager itemManager;

	@Inject
	private ItemIcons icons;

	@Inject
	private SpoonApi api;

	@Inject
	private Medals medals;

	@Inject
	private java.util.concurrent.ScheduledExecutorService executor;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChatMessageManager chatMessages;

	@Inject
	private WhoSpoonedItConfig config;

	private NavigationButton navigationButton;

	@Provides
	WhoSpoonedItConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WhoSpoonedItConfig.class);
	}

	@Override
	protected void startUp()
	{
		// Registered by hand rather than being a plugin of its own, so it stops listening the moment
		// this plugin is switched off.
		eventBus.register(watcher);
		watcher.setOnCaptured(this::record);

		spoons.load();
		groups.load();

		// An open leaderboard catches up on its own once drops land, rather than waiting for a press.
		sender.setOnSent(this::onDropsSent);
		sender.start();

		// Wired here rather than inside the panel, so the panel stays a view and does not have to know
		// how a group gets made.
		panel.setActions(this::createGroup, this::joinGroup, this::openGroup);

		navigationButton = NavigationButton.builder()
			.tooltip("Who Spooned It?")
			.icon(icon())
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown()
	{
		sender.stop();
		eventBus.unregister(watcher);
		clientToolbar.removeNavigation(navigationButton);
	}

	/**
	 * A drop has been seen. Kept, and said out loud if the player wants it said.
	 */
	private void record(Spoon spoon)
	{
		if (!spoons.add(spoon))
		{
			// Already had it. The log announces a slot the first time it fills, so this means a repeat
			// rather than a second drop, and the first record is the one worth keeping.
			return;
		}

		panel.refresh();

		// Off to every group this account is in. A drop is not shared with one and hidden from another.
		sender.nudge();

		if (config.announceInChat() && spoon.isScored())
		{
			announce(spoon);
		}
	}

	private void announce(Spoon spoon)
	{
		int top = Math.max(1, (int) Math.round(spoon.getShare() * 100));
		String verdict = Luck.isSpooned(spoon.getShare()) ? "Spooned!" : "About time.";

		chatMessages.queue(QueuedMessage.builder()
			.type(net.runelite.api.ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(String.format(
				"%s %s on kill %d, top %d%% of everyone who went for it.",
				verdict, spoon.getItemName(), spoon.getKillCount(), top))
			.build());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			// Drops are stored per account, so they cannot be read until there is an account to read
			// them for. Logging in on a second character swaps them over rather than merging them.
			spoons.load();
			groups.load();
			panel.refresh();
		}
	}

	/**
	 * Drops have reached a group. Only the open group screen is redrawn, and only by reopening it,
	 * since the leaderboard it shows is the service's rather than anything held here.
	 */
	/**
	 * Brings back anything a group knows about this account that this client never saw.
	 * <p>
	 * An import or a carried claim lands on the service, not here, so without this the group would
	 * credit somebody with a spoon while their own front screen said nothing had ever happened. Two
	 * different questions, one of which looks like a broken plugin.
	 * <p>
	 * Run after an import and after a claim carries, which are the only two ways it can happen.
	 */
	private void catchUpFromGroup(String code)
	{
		String rsn = localPlayerName();
		if (rsn == null)
		{
			return;
		}

		executor.execute(() ->
		{
			SpoonApi.Result<SpoonApi.MemberDrops> result =
				api.memberDrops(config.serverUrl(), code, rsn, "recent");

			if (!result.ok())
			{
				return;
			}

			SwingUtilities.invokeLater(() ->
			{
				int taken = 0;

				for (com.spoon.data.Holder held : result.getValue().getDrops())
				{
					com.spoon.data.Spoon spoon = new com.spoon.data.Spoon();
					spoon.setItemName(held.getItemName());
					spoon.setItemId(held.getItemId());
					spoon.setSource(held.getSource() == null ? "" : held.getSource());
					spoon.setKillCount(held.getKillCount() == null ? -1 : held.getKillCount());
					spoon.setDenominator(held.getDenominator() == null ? -1 : held.getDenominator());
					spoon.setShare(held.getShare() == null ? -1 : held.getShare());
					spoon.setObtainedAt(held.getObtainedAt());

					// Marked as claimed whatever it was, because this client did not see it happen.
					spoon.setClaimed(true);

					// Already recorded on the service under its own id, so it must never be sent back.
					if (spoons.take(spoon))
					{
						groups.markSent(code, java.util.Collections.singletonList(spoon.getId()));
						taken++;
					}
				}

				if (taken > 0)
				{
					log.debug("Took {} drops back from {}", taken, code);
					panel.refresh();
				}
			});
		});
	}

	private void onDropsSent()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (openView != null && openCode != null)
			{
				openGroup(openCode);
			}
			else
			{
				panel.refresh();
			}
		});
	}

	private void createGroup()
	{
		openView = null;
		openCode = null;
		openClaims = null;
		panel.show(new CreateGroupPanel(this::doCreate, panel::showList));
	}

	private void joinGroup()
	{
		openView = null;
		openCode = null;
		openClaims = null;
		panel.show(new JoinGroupPanel(this::doJoin, panel::showList));
	}

	private void doCreate(String name)
	{
		String rsn = localPlayerName();
		if (rsn == null)
		{
			warn("Log in first, a group is joined under your own name.");
			return;
		}

		executor.execute(() ->
		{
			SpoonApi.Result<SpoonApi.Snapshot> result = api.create(config.serverUrl(), name, rsn);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					warn(result.getError());
					return;
				}

				SpoonApi.Snapshot snapshot = result.getValue();
				groups.put(snapshot.getGroup(), snapshot.getCreatorToken(), snapshot.getMemberToken());
				openGroup(snapshot.getGroup().getCode());
			});
		});
	}

	private void doJoin(String code)
	{
		String rsn = localPlayerName();
		if (rsn == null)
		{
			warn("Log in first, a group is joined under your own name.");
			return;
		}

		executor.execute(() ->
		{
			SpoonApi.Result<SpoonApi.Snapshot> result = api.join(config.serverUrl(), code, rsn);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					warn(result.getError());
					return;
				}

				SpoonApi.Snapshot snapshot = result.getValue();
				groups.put(snapshot.getGroup(), null, snapshot.getMemberToken());
				openGroup(snapshot.getGroup().getCode());
			});
		});
	}

	private void openGroup(String code)
	{
		executor.execute(() ->
		{
			SpoonApi.Result<SpoonApi.Snapshot> result = api.read(config.serverUrl(), code);

			SwingUtilities.invokeLater(() ->
			{
				if (result.isGone())
				{
					// The service answered and said there is no such group: whoever made it deleted it.
					// Keeping it on the list means a card that cannot be opened and cannot be removed.
					forget(code);
					return;
				}

				if (!result.ok())
				{
					warn(result.getError());
					panel.showList();
					return;
				}

				SpoonApi.Snapshot snapshot = result.getValue();
				groups.put(snapshot.getGroup(), null, null);

				boolean creator = groups.creatorTokenFor(code) != null;

				GroupView view = new GroupView(
					snapshot.getGroup(),
					snapshot.getLeaderboard(),
					localPlayerName(),
					creator,
					medals::label,
					query -> search(code, query),
					panel::showList,
					() -> openGroup(code),
					() -> leave(code, creator),
					earlierDrops(code),
					() -> shareEarlier(code),
					() -> importFromDiscord(code),
					claimsPanel(code),
					() -> claimADrop(code),
					who -> openMember(code, who, "recent"));

				panel.show(view);
				this.openView = view;
				this.openCode = code;

				// Opening a group is the moment to reconcile: anything it knows about this account that
				// this client never saw belongs on the front screen too. Cheap, because a drop already
				// taken is skipped by name, and it is the only place somebody would notice the two
				// disagreeing.
				catchUpFromGroup(code);
			});
		});
	}

	/** Held so search results can be filled into the group screen that asked for them. */
	private GroupView openView;

	/** Which group that screen is showing, so a send can refresh the right one. */
	private String openCode;

	/** The claims section of the open group, filled in once the service answers. */
	private ClaimsPanel openClaims;

	private void search(String code, String query)
	{
		if (query == null || query.trim().length() < 2)
		{
			if (openView != null)
			{
				openView.showSearchMessage("Type at least two letters of an item's name.");
			}

			return;
		}

		GroupView asked = openView;
		asked.showSearchMessage("Looking...");

		executor.execute(() ->
		{
			SpoonApi.Result<java.util.List<com.spoon.data.Holder>> result =
				api.whoSpoonedIt(config.serverUrl(), code, query.trim());

			SwingUtilities.invokeLater(() ->
			{
				// Only if that same screen is still up. A slow answer arriving after someone has gone
				// back should change nothing.
				if (openView != asked)
				{
					return;
				}

				if (!result.ok())
				{
					asked.showSearchMessage(result.getError());
					return;
				}

				asked.showHolders(query.trim(), result.getValue(), medals::label, icons);
			});
		});
	}

	/**
	 * How many recorded drops predate joining this group, and so have not been shared.
	 * <p>
	 * Counted against everything already sent, so the offer disappears once it has been taken up
	 * rather than sitting there claiming there is more to give.
	 */
	private int earlierDrops(String code)
	{
		com.spoon.track.GroupStore.Membership membership = groups.find(code);
		if (membership == null || membership.sharedFrom == 0)
		{
			return 0;
		}

		int earlier = 0;
		for (com.spoon.data.Spoon spoon : spoons.all())
		{
			if (spoon.getObtainedAt() < membership.sharedFrom
				&& (membership.sent == null || !membership.sent.contains(spoon.getId())))
			{
				earlier++;
			}
		}

		return earlier;
	}

	private void shareEarlier(String code)
	{
		int answer = javax.swing.JOptionPane.showConfirmDialog(
			panel,
			"Share every drop already recorded on this account with this group?"
				+ System.lineSeparator() + System.lineSeparator()
				+ "They will appear on its leaderboard and in its searches.",
			"Who Spooned It?",
			javax.swing.JOptionPane.YES_NO_OPTION);

		if (answer != javax.swing.JOptionPane.YES_OPTION)
		{
			return;
		}

		groups.shareEverything(code);

		// Gone from the screen at once. The send follows in a few seconds, and waiting for it would
		// leave the card offering what has just been handed over.
		if (openView != null)
		{
			openView.setEarlierDrops(0);
		}

		sender.nudge();
	}

	/**
	 * One member's drops, on their own.
	 * <p>
	 * The screen is drawn from the same answer that fills it, so the totals at the top and the list
	 * below can never disagree, which they would if the panel were built from the leaderboard and then
	 * filled from a second call.
	 */
	private void openMember(String code, String rsn, String sort)
	{
		openView = null;
		openClaims = null;

		// Something on screen before the request goes out. A press that leaves the old screen sitting
		// there for a second reads as a press that did not register, and the natural response to that
		// is to press again.
		busy("Loading " + rsn + "...");

		executor.execute(() ->
		{
			SpoonApi.Result<SpoonApi.MemberDrops> result =
				api.memberDrops(config.serverUrl(), code, rsn, sort);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					warn(result.getError());
					openGroup(code);
					return;
				}

				SpoonApi.MemberDrops drops = result.getValue();

				MemberView view = new MemberView(
					drops.getRsn(),
					drops.getSpoons(),
					drops.getScored(),
					drops.getAvgShare(),
					drops.getSort(),
					icons,
					chosen -> openMember(code, rsn, chosen),
					() -> openGroup(code));

				view.show(drops.getDrops());
				panel.show(view);
			});
		});
	}

	/**
	 * The claims section, empty until the service answers.
	 * <p>
	 * Loaded after the screen is drawn rather than before it, so a slow answer holds nothing up.
	 */
	private ClaimsPanel claimsPanel(String code)
	{
		ClaimsPanel claims = new ClaimsPanel(
			(claimId, approve) -> vote(code, claimId, approve),
			net.runelite.client.util.LinkBrowser::browse);

		openClaims = claims;
		claims.showMessage("Looking...");
		refreshClaims(code, claims);

		return claims;
	}

	private void refreshClaims(String code, ClaimsPanel into)
	{
		String token = groups.memberTokenFor(code);
		if (token == null)
		{
			into.showMessage("Join this group to see what it is voting on.");
			return;
		}

		executor.execute(() ->
		{
			SpoonApi.Result<java.util.List<com.spoon.data.Claim>> result =
				api.claims(config.serverUrl(), code, token);

			SwingUtilities.invokeLater(() ->
			{
				// Only if that same section is still on screen. A slow answer arriving after someone has
				// gone back should change nothing.
				if (openClaims != into)
				{
					return;
				}

				if (!result.ok())
				{
					into.showMessage(result.getError());
					return;
				}

				into.show(result.getValue());
			});
		});
	}

	private void claimADrop(String code)
	{
		openView = null;
		openCode = null;
		openClaims = null;
		panel.show(new ClaimPanel(claim -> submitClaim(code, claim), () -> openGroup(code)));
	}

	private void submitClaim(String code, com.spoon.data.Claim claim)
	{
		String token = groups.memberTokenFor(code);
		if (token == null)
		{
			warn("Join this group before claiming anything.");
			return;
		}

		// Looked up here rather than typed, so a claim is scored on the same rate as a drop the plugin
		// watched. Nobody gets to name their own odds.
		if (claim.getSource() != null && !claim.getSource().isEmpty())
		{
			for (com.spoon.data.DropRates.Drop drop : dropRates.dropsFrom(claim.getSource()))
			{
				net.runelite.api.ItemComposition composition =
					itemManager.getItemComposition(drop.itemId);

				if (composition != null && claim.getItemName().equalsIgnoreCase(composition.getName()))
				{
					claim.setItemId(drop.itemId);
					claim.setDenominator(drop.denominator);
					break;
				}
			}
		}

		executor.execute(() ->
		{
			SpoonApi.Result<java.util.List<com.spoon.data.Claim>> result =
				api.claim(config.serverUrl(), code, token, claim);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					warn(result.getError());
					return;
				}

				warn("Put to the group. They will vote on it.");
				openGroup(code);
			});
		});
	}

	private void vote(String code, String claimId, boolean approve)
	{
		String token = groups.memberTokenFor(code);
		if (token == null)
		{
			return;
		}

		executor.execute(() ->
		{
			SpoonApi.Result<String> result = api.vote(config.serverUrl(), code, token, claimId, approve);

			SwingUtilities.invokeLater(() ->
			{
				if (!result.ok())
				{
					warn(result.getError());
					return;
				}

				String settled = result.getValue();
				if (settled == null)
				{
					// Still waiting on other people; only the tally has moved.
					if (openCode != null && openClaims != null)
					{
						refreshClaims(openCode, openClaims);
					}

					return;
				}

				// Settled, so the leaderboard has moved too and the whole screen is stale.
				warn("accepted".equals(settled)
					? "Carried. It is on the board, marked as claimed."
					: "Not carried.");

				if ("accepted".equals(settled))
				{
					catchUpFromGroup(code);
				}

				openGroup(code);
			});
		});
	}

	/**
	 * Brings in the group's history from its Discord channel.
	 * <p>
	 * Asked about first, always. An import that silently discarded a third of a channel is one nobody
	 * would trust afterwards, so what was found is put in front of the creator before anything is
	 * kept, including whose names were not recognised, since a name that has been changed is the
	 * commonest reason for a drop to go missing.
	 */
	private void importFromDiscord(String code)
	{
		String creatorToken = groups.creatorTokenFor(code);
		if (creatorToken == null)
		{
			warn("Only whoever made this group can import its history.");
			return;
		}

		executor.execute(() ->
		{
			SpoonApi.Result<SpoonApi.Import> look =
				api.importFromDiscord(config.serverUrl(), code, creatorToken, true,
					running -> showProgress("Read " + count(running.getFound() + running.getSkipped())
						+ " messages"));

			SwingUtilities.invokeLater(() ->
			{
				showProgress("");

				if (!look.ok())
				{
					warn(look.getError());
					return;
				}

				SpoonApi.Import found = look.getValue();

				if (found.isNeedsBot())
				{
					offerInvite(found);
					return;
				}

				if (found.getMatched() == 0)
				{
					warn(describe(found) + System.lineSeparator() + System.lineSeparator()
						+ "Nothing to bring in.");
					return;
				}

				int answer = javax.swing.JOptionPane.showConfirmDialog(
					panel,
					describe(found) + System.lineSeparator() + System.lineSeparator() + "Bring them in?",
					"Who Spooned It?",
					javax.swing.JOptionPane.YES_NO_OPTION);

				if (answer != javax.swing.JOptionPane.YES_OPTION)
				{
					return;
				}

				executor.execute(() ->
				{
					SpoonApi.Result<SpoonApi.Import> done =
						api.importFromDiscord(config.serverUrl(), code, creatorToken, false,
							running -> showProgress("Brought in " + count(running.getImported())
								+ " drops"));

					SwingUtilities.invokeLater(() ->
					{
						showProgress("");

						if (!done.ok())
						{
							warn(done.getError());
							return;
						}

						warn("Brought in " + count(done.getValue().getImported()) + " drops.");

						// Whatever of that was this account's own belongs on the front screen too.
						catchUpFromGroup(code);
						openGroup(code);
					});
				});
			});
		});
	}

	/**
	 * Says how far through the channel an import has got.
	 *
	 * A clan's Discord history takes as long as it takes to read, and a panel that sits there saying
	 * nothing for a minute is one that gets pressed again, or closed.
	 */
	private void showProgress(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (openView != null)
			{
				openView.importProgress(text);
			}
		});
	}

	/** Thousands separated, because six thousand and sixty thousand look alike in a hurry. */
	private static String count(int number)
	{
		return String.format("%,d", number);
	}

	/**
	 * Offers to open Discord so the bot can be added, rather than telling someone to go and do it.
	 * <p>
	 * Through LinkBrowser, which is the sanctioned way for a plugin to open a web page, and the only
	 * one. Opening a local path is restricted on the plugin hub; a link is not.
	 */
	private void offerInvite(SpoonApi.Import found)
	{
		if (found.getInvite() == null)
		{
			warn("This service has no Discord bot set up.");
			return;
		}

		int answer = javax.swing.JOptionPane.showConfirmDialog(
			panel,
			"The bot is not in your Discord server yet." + System.lineSeparator()
				+ System.lineSeparator()
				+ "Open Discord to add it? You will need someone who can manage the server."
				+ System.lineSeparator() + System.lineSeparator()
				+ "Once it is in, type this in the channel your Dink messages go to:"
				+ System.lineSeparator() + "    " + found.getLinkCommand(),
			"Who Spooned It?",
			javax.swing.JOptionPane.YES_NO_OPTION);

		if (answer == javax.swing.JOptionPane.YES_OPTION)
		{
			net.runelite.client.util.LinkBrowser.browse(found.getInvite());
		}
	}

	/** What the import found, in words rather than numbers on their own. */
	private String describe(SpoonApi.Import found)
	{
		StringBuilder text = new StringBuilder();
		text.append("Found ").append(found.getFound()).append(" collection log messages.")
			.append(System.lineSeparator())
			.append(found.getMatched()).append(" belong to people in this group.");

		if (found.getWithoutKillCount() > 0)
		{
			text.append(System.lineSeparator())
				.append(found.getWithoutKillCount())
				.append(" have no kill count, so they count but cannot be scored.");
		}

		if (found.getWithoutRate() > 0)
		{
			// Said apart from the above because it is a different hole and has a different answer: a
			// missing kill count is gone for good, while a missing rate is a monster nothing has the
			// odds for yet, and importing again once it does will fill it in.
			text.append(System.lineSeparator())
				.append(found.getWithoutRate())
				.append(" are from something with no known drop rate, so they count but are not scored"
					+ " yet.");
		}

		if (!found.getUnmatched().isEmpty())
		{
			text.append(System.lineSeparator()).append(System.lineSeparator())
				.append("Not in this group, and ignored:");

			int shown = 0;
			for (java.util.Map.Entry<String, Integer> entry : found.getUnmatched().entrySet())
			{
				if (shown++ == 6)
				{
					text.append(System.lineSeparator()).append("  and others");
					break;
				}

				text.append(System.lineSeparator()).append("  ").append(entry.getKey())
					.append(" (").append(entry.getValue()).append(")");
			}
		}

		return text.toString();
	}

	private void leave(String code, boolean creator)
	{
		String question = creator
			? "Delete this group? It goes for everyone in it, along with every drop recorded in it."
			: "Leave this group? Your drops stay on your own machine.";

		int answer = javax.swing.JOptionPane.showConfirmDialog(
			panel, question, "Who Spooned It?", javax.swing.JOptionPane.YES_NO_OPTION);

		if (answer != javax.swing.JOptionPane.YES_OPTION)
		{
			return;
		}

		String creatorToken = groups.creatorTokenFor(code);

		if (creator && creatorToken != null)
		{
			executor.execute(() -> api.delete(config.serverUrl(), code, creatorToken));
		}

		groups.remove(code);
		panel.showList();
	}

	/** Takes a group that no longer exists off this account's list, once the player says so. */
	private void forget(String code)
	{
		int answer = javax.swing.JOptionPane.showConfirmDialog(
			panel,
			"That group no longer exists. Remove it from your list?",
			"Who Spooned It?",
			javax.swing.JOptionPane.YES_NO_OPTION);

		if (answer == javax.swing.JOptionPane.YES_OPTION)
		{
			groups.remove(code);
		}

		panel.showList();
	}

	/** A holding screen, so a press always does something visible at once. */
	private void busy(String message)
	{
		javax.swing.JPanel waiting = new javax.swing.JPanel();
		waiting.setLayout(new javax.swing.BoxLayout(waiting, javax.swing.BoxLayout.Y_AXIS));
		waiting.setBackground(com.spoon.ui.Theme.BACKGROUND);
		waiting.setBorder(javax.swing.BorderFactory.createEmptyBorder(20, 0, 0, 0));

		javax.swing.JLabel label = new javax.swing.JLabel(message);
		label.setFont(com.spoon.ui.Theme.body());
		label.setForeground(com.spoon.ui.Theme.TEXT_MUTED);
		label.setAlignmentX(java.awt.Component.LEFT_ALIGNMENT);
		waiting.add(label);

		panel.show(waiting);
	}

	private void warn(String message)
	{
		javax.swing.JOptionPane.showMessageDialog(
			panel, message, "Who Spooned It?", javax.swing.JOptionPane.INFORMATION_MESSAGE);
	}

	/** The name drops are recorded under. Null until logged in. */
	private String localPlayerName()
	{
		return client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
	}

	/**
	 * The sidebar icon: a spoon, drawn rather than shipped as a file so there is one less thing for the
	 * plugin hub's packaging to get wrong.
	 */
	private BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		graphics.setColor(new Color(240, 176, 62));
		graphics.fillOval(5, 1, 6, 7);
		graphics.fillRoundRect(7, 7, 2, 8, 2, 2);

		graphics.dispose();
		return image;
	}
}

package com.spoon.track;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.spoon.data.Group;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The groups this account is in, and the tokens that prove it.
 * <p>
 * More than one is expected. A clan competition and a group of mates are different arguments about
 * the same collection log, and being in both should not mean choosing.
 */
@Slf4j
@Singleton
public class GroupStore
{
	private static final String CONFIG_GROUP = "whospoonedit";
	private static final String KEY = "groups";

	/** One group, with whatever this account is allowed to do in it. */
	public static class Membership
	{
		public Group group = new Group();

		/** Held only by whoever created it. Its absence is what hides the creator's controls. */
		public String creatorToken;

		public String memberToken;

		/**
		 * Drops from this moment on are shared with this group; earlier ones are not.
		 * <p>
		 * Set to the moment of joining, because joining a group should not hand over a collection log
		 * built up over years without being asked. Pressing "share my earlier drops" sets it to zero,
		 * which is that asking.
		 */
		public long sharedFrom;

		/** Ids the service has taken, so nothing is sent twice and a failure can be retried. */
		public java.util.Set<String> sent = new java.util.HashSet<>();

		public boolean isCreator()
		{
			return creatorToken != null && !creatorToken.isEmpty();
		}
	}

	private final ConfigManager configManager;
	private final Gson gson;

	private final List<Membership> memberships = new ArrayList<>();

	@Inject
	private GroupStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void load()
	{
		memberships.clear();

		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		Type type = new TypeToken<List<Membership>>()
		{
		}.getType();

		try
		{
			List<Membership> saved = gson.fromJson(json, type);
			if (saved != null)
			{
				memberships.addAll(saved);
			}
		}
		catch (JsonSyntaxException e)
		{
			// Never drop the lot because one entry is unreadable; that would quietly remove someone from
			// a group they had joined, along with the token that proves they belong.
			log.warn("Could not read saved groups", e);
		}
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY, gson.toJson(memberships));
	}

	public List<Membership> all()
	{
		return Collections.unmodifiableList(memberships);
	}

	@Nullable
	public Membership find(String code)
	{
		for (Membership membership : memberships)
		{
			if (membership.group.getCode().equalsIgnoreCase(code))
			{
				return membership;
			}
		}

		return null;
	}

	/**
	 * Adds a group, or updates one already known. Tokens already held are kept when the incoming copy
	 * has none, a refresh carries the group but not the secrets.
	 */
	public void put(Group group, @Nullable String creatorToken, @Nullable String memberToken)
	{
		Membership existing = find(group.getCode());

		if (existing == null)
		{
			existing = new Membership();
			memberships.add(existing);
		}

		existing.group = group;

		if (creatorToken != null && !creatorToken.isEmpty())
		{
			existing.creatorToken = creatorToken;
		}

		if (memberToken != null && !memberToken.isEmpty())
		{
			// The moment of joining, and only the first time: a later refresh must not move the line and
			// quietly un-share what has already gone.
			if (existing.memberToken == null)
			{
				existing.sharedFrom = System.currentTimeMillis();
			}

			existing.memberToken = memberToken;
		}

		save();
	}

	/** Records that these drops have landed, so they are not sent again. */
	public void markSent(String code, java.util.Collection<String> ids)
	{
		Membership membership = find(code);
		if (membership == null)
		{
			return;
		}

		if (membership.sent == null)
		{
			membership.sent = new java.util.HashSet<>();
		}

		membership.sent.addAll(ids);
		save();
	}

	/**
	 * Shares everything already recorded with this group, from here on.
	 * <p>
	 * The deliberate act the join screen promises: nothing you already have goes anywhere until you
	 * press the button.
	 */
	public void shareEverything(String code)
	{
		Membership membership = find(code);
		if (membership != null)
		{
			membership.sharedFrom = 0;
			save();
		}
	}

	public void remove(String code)
	{
		memberships.removeIf(membership -> membership.group.getCode().equalsIgnoreCase(code));
		save();
	}

	@Nullable
	public String memberTokenFor(String code)
	{
		Membership membership = find(code);
		return membership == null ? null : membership.memberToken;
	}

	@Nullable
	public String creatorTokenFor(String code)
	{
		Membership membership = find(code);
		return membership == null ? null : membership.creatorToken;
	}
}

package com.spoon.track;

import com.spoon.WhoSpoonedItConfig;
import com.spoon.data.Spoon;
import com.spoon.net.SpoonApi;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Sends this account's drops to the groups it is in.
 *
 * <p>Nothing is worked out here. What a drop is worth is the service's business; this decides only
 * what has not been sent yet.
 *
 * <p>A collection log slot is filled a few times a week at best, so there is no batching problem to
 * solve, the timer exists to catch what a failed send left behind, and everything else goes within
 * seconds of happening.
 */
@Slf4j
@Singleton
public class DropSender
{
	/** The safety net: picks up anything a failed send or a closed client left behind. */
	private static final int EVERY_SECONDS = 120;

	/** How long after a drop it goes out. Long enough to gather a double drop, short enough to feel live. */
	private static final int SOON_SECONDS = 5;

	/** The service takes 200 at a time; a first share of a long-standing log can exceed that. */
	private static final int BATCH = 100;

	private final ScheduledExecutorService executor;
	private final SpoonStore spoons;
	private final GroupStore groups;
	private final SpoonApi api;
	private final WhoSpoonedItConfig config;

	private ScheduledFuture<?> scheduled;
	private ScheduledFuture<?> soon;

	/** Told after anything lands, so an open leaderboard catches up on its own. */
	private Runnable onSent = () ->
	{
	};

	@Inject
	private DropSender(
		ScheduledExecutorService executor,
		SpoonStore spoons,
		GroupStore groups,
		SpoonApi api,
		WhoSpoonedItConfig config)
	{
		this.executor = executor;
		this.spoons = spoons;
		this.groups = groups;
		this.api = api;
		this.config = config;
	}

	public void setOnSent(Runnable onSent)
	{
		this.onSent = onSent;
	}

	public void start()
	{
		stop();
		scheduled = executor.scheduleWithFixedDelay(
			this::flush, EVERY_SECONDS, EVERY_SECONDS, TimeUnit.SECONDS);
	}

	public void stop()
	{
		if (scheduled != null)
		{
			scheduled.cancel(false);
			scheduled = null;
		}

		if (soon != null)
		{
			soon.cancel(false);
			soon = null;
		}
	}

	/**
	 * Sends shortly rather than at the next sweep. Ignored if one is already on its way, so a double
	 * drop goes in one request.
	 */
	public synchronized void nudge()
	{
		if (soon != null && !soon.isDone())
		{
			return;
		}

		soon = executor.schedule((Runnable) this::flush, SOON_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * Sends whatever each group has not had yet. Safe to call at any time and safe to call twice: the
	 * ids mean a request that landed before timing out will not count again.
	 */
	public void flush()
	{
		try
		{
			boolean sentAnything = false;

			for (GroupStore.Membership membership : new ArrayList<>(groups.all()))
			{
				sentAnything |= flush(membership);
			}

			if (sentAnything)
			{
				onSent.run();
			}
		}
		catch (Exception e)
		{
			// A scheduled task that throws stops being scheduled, which would quietly end all sharing.
			log.warn("Sending failed", e);
		}
	}

	private boolean flush(GroupStore.Membership membership)
	{
		String code = membership.group.getCode();
		String token = membership.memberToken;

		if (token == null || token.isEmpty())
		{
			// Joined on another account, or the group was only ever created and never joined from here.
			return false;
		}

		List<Spoon> waiting = unsent(membership);
		if (waiting.isEmpty())
		{
			return false;
		}

		boolean sentAnything = false;

		// Sent in batches, because a first share of a log built up over years is hundreds of drops and
		// the service takes a couple of hundred at a time.
		for (int from = 0; from < waiting.size(); from += BATCH)
		{
			List<Spoon> batch = waiting.subList(from, Math.min(from + BATCH, waiting.size()));

			SpoonApi.Result<SpoonApi.Snapshot> result =
				api.submit(config.serverUrl(), code, token, batch);

			if (!result.ok())
			{
				// Left unsent on purpose. The next run tries again, and nothing is marked as landed that
				// did not land.
				log.debug("Could not send {} drops to {}: {}", batch.size(), code, result.getError());
				break;
			}

			List<String> ids = new ArrayList<>(batch.size());
			for (Spoon spoon : batch)
			{
				ids.add(spoon.getId());
			}

			groups.markSent(code, ids);
			sentAnything = true;
		}

		return sentAnything;
	}

	/**
	 * What this group has not been told about: everything recorded since sharing began, less whatever
	 * has already landed.
	 */
	private List<Spoon> unsent(GroupStore.Membership membership)
	{
		List<Spoon> waiting = new ArrayList<>();

		for (Spoon spoon : spoons.all())
		{
			if (spoon.getObtainedAt() < membership.sharedFrom)
			{
				// From before this account joined, and not asked to be shared.
				continue;
			}

			if (membership.sent != null && membership.sent.contains(spoon.getId()))
			{
				continue;
			}

			waiting.add(spoon);
		}

		return waiting;
	}

	/** How many drops a group has not been told about, for the button that offers to send them. */
	public int waitingFor(String code)
	{
		GroupStore.Membership membership = groups.find(code);
		return membership == null ? 0 : unsent(membership).size();
	}
}

package com.spoon.track;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.spoon.data.Spoon;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Every collection log drop this account has been seen getting.
 * <p>
 * Kept on the player's own machine and useful on its own: the plugin works from the moment it is
 * installed, with no group, no code and nothing sent anywhere. Joining a group later adds the
 * comparison, it is not what makes the thing work.
 * <p>
 * Stored against the logged-in account rather than the installation, because two characters on one
 * computer have separate collection logs and merging them would be nonsense.
 */
@Slf4j
@Singleton
public class SpoonStore
{
	private static final String CONFIG_GROUP = "whospoonedit";
	private static final String KEY = "spoons";

	private final ConfigManager configManager;
	private final Gson gson;

	private final List<Spoon> spoons = new ArrayList<>();

	@Inject
	private SpoonStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void load()
	{
		spoons.clear();

		if (configManager.getRSProfileKey() == null)
		{
			// No account yet, so nothing to read. Called again on login.
			return;
		}

		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		Type type = new TypeToken<List<Spoon>>()
		{
		}.getType();

		try
		{
			List<Spoon> saved = gson.fromJson(json, type);
			if (saved != null)
			{
				spoons.addAll(saved);
			}
		}
		catch (JsonSyntaxException e)
		{
			// Never throw the lot away because one entry is unreadable. Someone's drop history is not
			// recoverable if this class deletes it.
			log.warn("Could not read saved drops", e);
		}

		log.debug("Loaded {} drops", spoons.size());
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY, gson.toJson(spoons));
	}

	/**
	 * Records a drop, unless this item is already here.
	 * <p>
	 * The collection log announces a slot the first time it is filled, so a repeat means something has
	 * gone wrong rather than that the player got it twice, a replayed chat line, or a re-import. The
	 * first record is the one that matters, because it is the one with the kill count that earns the
	 * spoon.
	 *
	 * @return whether it was new
	 */
	public boolean add(Spoon spoon)
	{
		if (spoon == null || spoon.getItemName().isEmpty() || has(spoon.getItemName()))
		{
			return false;
		}

		spoons.add(spoon);
		save();
		return true;
	}

	public boolean has(String itemName)
	{
		for (Spoon spoon : spoons)
		{
			if (spoon.getItemName().equalsIgnoreCase(itemName))
			{
				return true;
			}
		}

		return false;
	}

	/** Newest first, which is the order anyone wants to read them in. */
	public List<Spoon> all()
	{
		List<Spoon> copy = new ArrayList<>(spoons);
		copy.sort((a, b) -> Long.compare(b.getObtainedAt(), a.getObtainedAt()));
		return Collections.unmodifiableList(copy);
	}

	/** The scored ones, luckiest first. Unscored drops are left out rather than sorted as unlucky. */
	public List<Spoon> luckiestFirst()
	{
		List<Spoon> scored = new ArrayList<>();
		for (Spoon spoon : spoons)
		{
			if (spoon.isScored())
			{
				scored.add(spoon);
			}
		}

		scored.sort((a, b) -> Double.compare(a.getShare(), b.getShare()));
		return scored;
	}

	public int count()
	{
		return spoons.size();
	}

	/** How many came in ahead of the drop rate, the ones worth arguing about. */
	public int spoonCount()
	{
		int spooned = 0;
		for (Spoon spoon : spoons)
		{
			if (com.spoon.data.Luck.isSpooned(spoon.getShare()))
			{
				spooned++;
			}
		}

		return spooned;
	}

	/**
	 * Takes in a drop a group knows about that this client never saw.
	 * <p>
	 * Imports and carried claims live only on the service until this runs. Without it the group would
	 * credit somebody with a spoon while their own front screen said nothing had ever happened, which
	 * reads as the plugin being broken rather than as two different questions being asked.
	 * <p>
	 * Marked as claimed so it is never mistaken for one this client watched, and never sent back: it
	 * came from the service and already has an id there.
	 *
	 * @return whether anything was new
	 */
	public boolean take(Spoon spoon)
	{
		if (spoon == null || spoon.getItemName().isEmpty() || has(spoon.getItemName()))
		{
			return false;
		}

		spoons.add(spoon);
		save();
		return true;
	}

	public void remove(String itemName)
	{
		spoons.removeIf(spoon -> spoon.getItemName().equalsIgnoreCase(itemName));
		save();
	}
}

package com.spoon.track;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.http.api.loottracker.LootRecordType;
import org.apache.commons.lang3.StringUtils;

/**
 * What kill count you were on when something dropped.
 * <p>
 * Deliberately reads counts that other plugins already keep rather than counting kills itself. That is
 * partly because they are better at it, the Chat Commands plugin stores the number the server told
 * you, which cannot drift, and partly to avoid a whole class of bug: a plugin that increments a
 * counter on a loot event double counts the moment two loot events fire for one kill, and RuneLite has
 * more than one way of announcing a kill. Reading a stored number cannot double anything.
 * <p>
 * Three sources, best first. The Chat Commands count comes from "Your Cockatrice kill count is: 65",
 * which is the server's own figure. The Loot Tracker's is inferred from kills it recorded, so it is
 * right for anything that always drops something and low for anything that does not.
 */
@Slf4j
@Singleton
public class KillCounts
{
	private final ConfigManager configManager;

	@Inject
	private KillCounts(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * @param source the monster as the game named it
	 * @return the kill count, or -1 when nothing knows it
	 */
	public int forSource(String source)
	{
		if (source == null || source.isEmpty())
		{
			return -1;
		}

		Integer announced = configManager.getRSProfileConfiguration(
			"killcount", cleanName(source), int.class);

		if (announced != null)
		{
			return announced;
		}

		return fromLootTracker(source);
	}

	/**
	 * The Loot Tracker's count of kills it has seen.
	 * <p>
	 * A fallback, and an undercount for anything that can die without dropping anything, because the
	 * Loot Tracker only records a kill when there was loot to record. Better than nothing for the
	 * ordinary monsters that never announce a kill count.
	 */
	private int fromLootTracker(String source)
	{
		String json = configManager.getConfiguration(
			"loottracker", configManager.getRSProfileKey(), "drops_" + LootRecordType.NPC + "_" + source);

		if (json == null)
		{
			return -1;
		}

		// Read by hand rather than through the Loot Tracker's own class, which is not ours to depend on
		// and would tie this to its internals.
		int at = json.indexOf("\"kills\"");
		if (at < 0)
		{
			return -1;
		}

		String digits = json.substring(at).replaceAll("^[^0-9-]*(-?[0-9]+).*$", "$1");

		try
		{
			return Integer.parseInt(digits);
		}
		catch (NumberFormatException e)
		{
			log.debug("Could not read a kill count out of the loot tracker for {}", source);
			return -1;
		}
	}

	/**
	 * How many caskets of a tier have been opened.
	 * <p>
	 * The game keeps this, and it is the kill count of a clue: how many goes it took. Which key the
	 * Chat Commands plugin files it under has changed with the wording of the message it reads, so
	 * every plausible spelling is tried rather than one being assumed, a wrong guess here does not
	 * fail loudly, it just quietly leaves every clue reward unscored.
	 *
	 * @param tier "hard", "master" and so on
	 * @return the count, or -1 when nothing knows it
	 */
	public int forClueTier(String tier)
	{
		if (tier == null || tier.isEmpty())
		{
			return -1;
		}

		String[] candidates = {
			"clue scroll (" + tier + ")",
			tier + " treasure trails",
			"treasure trails (" + tier + ")",
			"reward casket (" + tier + ")",
			tier
		};

		for (String key : candidates)
		{
			Integer count = configManager.getRSProfileConfiguration("killcount", key, int.class);
			if (count != null && count > 0)
			{
				return count;
			}
		}

		return -1;
	}

	/**
	 * The name the Chat Commands plugin files a boss under, which is not always the name the game uses
	 * when it dies.
	 */
	static String cleanName(String source)
	{
		if ("Crystalline Hunllef".equals(source) || "The Gauntlet".equalsIgnoreCase(source))
		{
			return "gauntlet";
		}

		if ("Corrupted Hunllef".equals(source))
		{
			return "corrupted gauntlet";
		}

		if ("The Leviathan".equalsIgnoreCase(source))
		{
			return "leviathan";
		}

		if ("The Whisperer".equalsIgnoreCase(source))
		{
			return "whisperer";
		}

		if ("The Hueycoatl".equalsIgnoreCase(source))
		{
			return "hueycoatl";
		}

		if (source.startsWith("Barrows"))
		{
			return "barrows chests";
		}

		return StringUtils.remove(source.toLowerCase(java.util.Locale.ROOT), ':');
	}
}

package com.spoon.track;

import com.spoon.data.ClueRewards;
import com.spoon.data.DropRates;
import com.spoon.data.Luck;
import com.spoon.data.Spoon;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;

/**
 * Catches a collection log item the moment it drops, and works out how lucky it was.
 * <p>
 * The game announces a new log slot in the chat and says nothing about what dropped it, so the source
 * has to come from the kill that just happened. That is what {@link #lastSource} is for: loot arrives
 * first, the chat line follows, and the two are joined here.
 * <p>
 * Nothing is counted in this class. The kill count is read from what other plugins already store, so
 * the fact that RuneLite has two ways of announcing a kill, and may fire both, cannot corrupt
 * anything: setting the same name twice is setting it once.
 */
@Slf4j
@Singleton
public class ClogWatcher
{
	private static final String ADDED = "New item added to your collection log: ";

	private final ItemManager itemManager;
	private final KillCounts killCounts;
	private final DropRates dropRates;
	private final ClueRewards clueRewards;

	/** What died most recently, which is what a log slot moments later is assumed to have come from. */
	private String lastSource;

	/** Told about each captured drop. Set by the plugin so this class need not know where it goes. */
	private java.util.function.Consumer<Spoon> onCaptured = spoon ->
	{
	};

	@Inject
	private ClogWatcher(
		ItemManager itemManager,
		KillCounts killCounts,
		DropRates dropRates,
		ClueRewards clueRewards)
	{
		this.itemManager = itemManager;
		this.killCounts = killCounts;
		this.dropRates = dropRates;
		this.clueRewards = clueRewards;
	}

	public void setOnCaptured(java.util.function.Consumer<Spoon> onCaptured)
	{
		this.onCaptured = onCaptured;
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (event.getComposition() != null)
		{
			lastSource = event.getComposition().getName();
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		// Both of these fire for a kill depending on how the server announced it, and either may be the
		// only one. Harmless to take both: this records what died, it does not count how often.
		NPC npc = event.getNpc();
		if (npc != null && npc.getName() != null)
		{
			lastSource = npc.getName();
		}
	}

	@Subscribe
	public void onLootReceived(net.runelite.client.plugins.loottracker.LootReceived event)
	{
		// Chests and caskets, which never die at your feet and so never fire the other two. This is how
		// a clue reward gets a source at all.
		if (event.getName() != null)
		{
			lastSource = event.getName();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		String message = event.getMessage();
		if (message == null)
		{
			return;
		}

		int at = message.indexOf(ADDED);
		if (at < 0)
		{
			return;
		}

		// The message carries the item's name with the game's own formatting around it.
		String itemName = stripTags(message.substring(at + ADDED.length())).trim();
		if (itemName.isEmpty())
		{
			return;
		}

		capture(itemName);
	}

	private void capture(String itemName)
	{
		Spoon spoon = new Spoon();
		spoon.setItemName(itemName);
		spoon.setObtainedAt(System.currentTimeMillis());
		spoon.setSource(lastSource == null ? "" : lastSource);

		// A clue is not a monster: no kill count in the ordinary sense, but the game does keep how many
		// caskets of that tier have been opened, which is the same question, how many goes it took.
		String tier = ClueRewards.tierOf(lastSource);

		int kc;
		double denominator;

		if (tier != null)
		{
			kc = killCounts.forClueTier(tier);
			denominator = clueRewards.denominatorFor(tier, itemName);
			spoon.setItemId(-1);
		}
		else
		{
			// Identified against what this monster actually drops, which settles the item and its rarity
			// in one pass and works for untradeables that a name lookup cannot find.
			DropRates.Drop match = matchIn(lastSource, itemName);
			spoon.setItemId(match == null ? -1 : match.itemId);
			denominator = match == null ? -1 : match.denominator;
			kc = killCounts.forSource(lastSource);
		}

		spoon.setKillCount(kc);
		spoon.setDenominator(denominator);

		// Anything missing leaves this at -1, which means "unscored" everywhere else. A clue scroll item
		// has no monster and no kill count, and pretending otherwise would put a made-up number on a
		// leaderboard.
		spoon.setShare(Luck.shareWhoHaveItBy(denominator, kc));

		log.debug("Collection log: {} from {} at kc {} (1 in {}) -> {}",
			itemName, spoon.getSource(), kc, denominator, spoon.getShare());

		onCaptured.accept(spoon);
	}

	/**
	 * Finds the dropped item among the things this monster drops.
	 * <p>
	 * Safe here: chat events are posted on the client thread, which is the only one allowed to read an
	 * item's composition.
	 */
	private DropRates.Drop matchIn(String source, String itemName)
	{
		for (DropRates.Drop drop : dropRates.dropsFrom(source))
		{
			ItemComposition composition = itemManager.getItemComposition(drop.itemId);
			if (composition != null && itemName.equalsIgnoreCase(composition.getName()))
			{
				return drop;
			}
		}

		return null;
	}

	private static String stripTags(String text)
	{
		return text.replaceAll("<[^>]*>", "");
	}
}
